    LaunchedEffect(isLocalInferenceRunning, streamingResponseText) {
        if (!BuildConfig.DEBUG || !isLocalInferenceRunning) return@LaunchedEffect
        val currentChunk = streamingResponseText?.takeIf { it.isNotBlank() } ?: return@LaunchedEffect
        if (currentChunk != lastStreamingAssistantChunkForDev) {
            assistantUpdateCountForDev += 1
            firstNonEmptyAssistantChunkSeenForDev = true
            lastStreamingAssistantChunkForDev = currentChunk
            localStreamingUiMetricsForDev.recordAppend(
                text = currentChunk,
                nowElapsedMs = SystemClock.elapsedRealtime(),
            )
        }
    }
    LaunchedEffect(streamingResponseText, isInferenceRunningUi) {
        val latestText = streamingResponseText
        if (latestText.isNullOrEmpty()) {
            streamingResponseTextForRender = latestText
            return@LaunchedEffect
        }

        val previousRendered = streamingResponseTextForRender.orEmpty()
        val appendedDelta = if (latestText.startsWith(previousRendered)) {
            latestText.substring(previousRendered.length)
        } else {
            latestText
        }
        val shouldRefreshRenderText = shouldRefreshRender(
            prev = previousRendered,
            next = latestText,
            isStreaming = isInferenceRunningUi,
        )

        if (shouldRefreshRenderText) {
            if (BuildConfig.DEBUG && isLocalInferenceRunning) {
                localStreamingUiMetricsForDev.recordRenderUpdate()
            }
            streamingResponseTextForRender = latestText
        }
    }
    LaunchedEffect(effectiveChatId, BuildConfig.DEBUG) {
        if (!BuildConfig.DEBUG) return@LaunchedEffect
        devUiAliveSeconds = 0
        while (true) {
            delay(1000)
            devUiAliveSeconds += 1
        }
    }
    val devStreamingTailLimitEnabled = BuildConfig.DEBUG && DEV_STREAMING_RENDER_TAIL_LIMIT_ENABLED
    val isStreamingRenderActive =
        isInferenceRunningUi || !localStreamingResponseText.isNullOrBlank()
    val assistantRenderTailLimitChars = DEV_STREAMING_RENDER_TAIL_LIMIT_CHARS
    val streamingResponseTextForDisplay = (
        streamingResponseTextForRender ?: streamingResponseText
        )?.let { renderText ->
        val shouldTrimForRender = devStreamingTailLimitEnabled || isStreamingRenderActive
        if (!shouldTrimForRender) return@let sanitizeAssistantMessageForDisplay(renderText)
        buildAssistantDisplayText(
            originalMessage = renderText,
            tailLimitChars = assistantRenderTailLimitChars,
        ).text
    }
    val devStreamingDisplayLineCount = remember(streamingResponseTextForDisplay) {
        streamingResponseTextForDisplay?.lineSequence()?.count() ?: 0
    }

    fun logStreamTrace(message: String) {
        Log.i("ChatScreen", message)
        appendLocalReflectionTrace(context, message)
    }

    fun debugLocalUiTrace(label: String, extra: String = "") {
        if (!BuildConfig.DEBUG) return
        val suffix = if (extra.isNotBlank()) " $extra" else ""
        val message = "[LOCAL_UI] $label$suffix"
        Log.i("ChatScreen", message)
        appendLocalReflectionTrace(context.applicationContext, message)
    }

    fun resetStreamingSpeechState(clearPlaybackFlag: Boolean = true) {
        streamingSpeechBuffer = ""
        streamingSpeechLastConsumedLength = 0
        streamingSpeechStartedForMessageId = null
        if (clearPlaybackFlag) {
            isStreamingSentencePlaybackActive = false
        }
    }

    fun stopTtsWithCleanup(
        suppressedMessageId: Int?,
        armTapGuards: Boolean,
    ) {
        suppressedTtsAssistantMessageId = suppressedMessageId

        ttsController.stop()
        viewModel.stopTtsPlayback()
        resetStreamingSpeechState()
        currentSpeakingAssistantMessageId = null
        stopButtonOwnerAssistantMessageId = null
        stopButtonOwnerSetAtMs = null

        pendingStopButtonOwnerClearJob?.cancel()
        pendingStopButtonOwnerClearJob = null
        pendingStopUiCooldownClearJob?.cancel()
        pendingStopUiCooldownClearJob = null
        pendingReplaySuppressClearJob?.cancel()
        pendingReplaySuppressClearJob = null

        if (armTapGuards) {
            ttsTapGuardEpoch += 1
            val guardEpoch = ttsTapGuardEpoch

            if (suppressedMessageId != null) {
                stopUiCooldownAssistantMessageId = suppressedMessageId
                suppressReplayAssistantMessageId = suppressedMessageId

                pendingStopUiCooldownClearJob = coroutineScope.launch {
                    delay(250)
                    if (
                        ttsTapGuardEpoch == guardEpoch &&
                        stopUiCooldownAssistantMessageId == suppressedMessageId
                    ) {
                        stopUiCooldownAssistantMessageId = null
                    }
                }

                pendingReplaySuppressClearJob = coroutineScope.launch {
                    delay(300)
                    if (
                        ttsTapGuardEpoch == guardEpoch &&
                        suppressReplayAssistantMessageId == suppressedMessageId
                    ) {
                        suppressReplayAssistantMessageId = null
                    }
                }
            } else {
                stopUiCooldownAssistantMessageId = null
                suppressReplayAssistantMessageId = null
            }
        } else {
            stopUiCooldownAssistantMessageId = null
            suppressReplayAssistantMessageId = null
        }
    }

    fun resetStreamingAssistantPlaceholderId(reason: String) {
        streamingGuardEpoch += 1
        val previousId = streamingAssistantMessageId
        if (previousId != null) {
            logStreamTrace("STREAM reset placeholder id from $previousId to null reason=$reason")
        }
        streamingAssistantMessageId = null
        lastPersistedStreamingAssistantText = null
    }

    fun cleanupDevQairt244NpuUiState(reason: String) {
        localStreamingResponseText = null
        pendingLocalUserMessageText = null
        showDelayedLocalRespondingPlaceholder = false
        suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
        resetStreamingSpeechState()
        resetStreamingAssistantPlaceholderId(reason = reason)
        pendingStopButtonOwnerClearJob?.cancel()
        pendingStopButtonOwnerClearJob = null
        pendingStopUiCooldownClearJob?.cancel()
        pendingStopUiCooldownClearJob = null
        pendingReplaySuppressClearJob?.cancel()
        pendingReplaySuppressClearJob = null
        suppressReplayAssistantMessageId = null
        stopUiCooldownAssistantMessageId = null
        currentSpeakingAssistantMessageId = null
        stopButtonOwnerAssistantMessageId = null
        stopButtonOwnerSetAtMs = null
        didReceiveRealLocalPartial = false
        realLocalPartialChunkCount = 0
        localStopRequested = false
        localInferenceEngineState = LocalInferenceEngineState.READY
        viewModel.resetUiState()
        isLocalInferenceRunning = false
        localInferenceJob = null
        File(context.applicationContext.filesDir, "qairt244_dev_npu_ui_cleanup_state.txt").writeText(
            listOf(
                "reason=$reason",
                "ui_cleanup_is_local_inference_running=false",
                "ui_cleanup_local_job_active=false",
                "ui_cleanup_local_stop_requested=false",
                "ui_cleanup_duplicate_guard=false",
                "ui_cleanup_streaming_assistant_placeholder=false",
                "ui_cleanup_stop_owner=false",
                "ui_cleanup_show_delayed_local_responding_placeholder=false",
                "ui_cleanup_local_inference_engine_state=READY",
                "ui_cleanup_reset_ui_state_called=true",
            ).joinToString(separator = "\n", postfix = "\n"),
        )
    }

    fun cancelStaleLocalGeneration(reason: String) {
        localGpuWatchdogJob?.cancel()
        localGpuWatchdogJob = null
        localInferenceJob?.cancel()
        localInferenceJob = null
        localStreamingResponseText = null
        pendingLocalUserMessageText = null
        showDelayedLocalRespondingPlaceholder = false
        npuStandardRouteS4PseudoStreamingActive = false
        npuStandardRouteStreamingSentenceTtsBlocked = false
        isLocalInferenceRunning = false
        localInferenceEngineState = LocalInferenceEngineState.READY
        resetStreamingAssistantPlaceholderId(reason = reason)
        stopTtsWithCleanup(
            suppressedMessageId = stopButtonOwnerAssistantMessageId
                ?: currentSpeakingAssistantMessageId
                ?: streamingSpeechStartedForMessageId,
            armTapGuards = false,
        )
    }

    fun showSafetyGuardBlockedConversationMessage(chatId: Int?) {
        coroutineScope.launch {
            if (chatId != null) {
                withContext(Dispatchers.IO) {
                    viewModel.insertAssistantMessageAndReturnId(
                        createAssistantMessage(
                            chatId = chatId,
                            response = SAFETY_GUARD_BLOCKED_USER_MESSAGE,
                            localSourceSummary = listOf(
                                "guard_state=blocked",
                                "last_safety_stage=$MEMORY_STAGE_SAFETY_GUARD_TRIGGERED",
                                "generate_invoked=false",
                            ).joinToString("\n"),
                            latestInferenceStats = InferenceStats(
                                modelName = "safety_guard_blocked",
                                finishReason = MEMORY_STAGE_SAFETY_GUARD_TRIGGERED,
                                localSourceSummary = "guard_state=blocked\ngenerate_invoked=false",
                            ),
                        ),
                    )
                }
            }
            snackbarHostState.currentSnackbarData?.dismiss()
            snackbarHostState.showSnackbar(
                message = SAFETY_GUARD_BLOCKED_USER_MESSAGE,
                duration = SnackbarDuration.Short,
            )
        }
    }

    fun recycleLocalEngineAfterSafetyGuard(chatId: Int?) {
        coroutineScope.launch(Dispatchers.IO) {
            chatId?.let { currentChatId ->
                localInferenceEngineHolder.resetConversation(
                    chatId = currentChatId,
                    reason = MEMORY_STAGE_SAFETY_GUARD_TRIGGERED,
                    appendTrace = { message ->
                        appendLocalReflectionTrace(
                            context = context.applicationContext,
                            message = message,
                        )
                    },
                )
            }
            localInferenceEngineHolder.requestRecreateForDev(
                reason = MEMORY_STAGE_SAFETY_GUARD_TRIGGERED,
                appendTrace = { message ->
                    appendLocalReflectionTrace(
                        context = context.applicationContext,
                        message = message,
                    )
                },
            )
        }
    }

    fun launchGpuExperimentalLocalRouteWatchdog(
        currentChatId: Int,
        diagnosticContext: LocalRouteDiagnosticContext,
        runGuardEpoch: Long,
        runStartedAtMs: Long,
        timedOut: AtomicBoolean,
        progressFlagsProvider: () -> LocalRouteDiagnosticFlags = { LocalRouteDiagnosticFlags() },
    ): Job? {
        if (!shouldApplyGpuExperimentalStageTimeout(diagnosticContext)) return null
        return coroutineScope.launch {
            delay(GPU_EXPERIMENTAL_STAGE_TIMEOUT_MS)
            if (timedOut.get()) return@launch
            if (runGuardEpoch != streamingGuardEpoch) return@launch
            if (!isLocalInferenceRunning || didReceiveRealLocalPartial || localStopRequested) return@launch

            timedOut.set(true)
            val elapsedMs = SystemClock.elapsedRealtime() - runStartedAtMs
            val holderSnapshotBeforeTimeoutCleanup = withContext(Dispatchers.IO) {
                localInferenceEngineHolder.getDevDiagnosticSnapshot()
            }
            val diagnosticsText = buildGpuExperimentalTimeoutDiagnosticsText(
                context = diagnosticContext,
                failureStage = "gpu_watchdog_timeout",
                elapsedMs = elapsedMs,
                staleCallbackIgnored = true,
                progressFlags = progressFlagsProvider().withHeldEngineSnapshot(holderSnapshotBeforeTimeoutCleanup),
            )
            appendLocalReflectionTrace(
                context = context.applicationContext,
                message = diagnosticsText,
            )
            latestLocalTraceForDev = LocalInferenceTrace(
                localModelDisplayName = diagnosticContext.selectedModelName,
                mediaPipeProbeModelPath = diagnosticContext.selectedModelPath,
                requestedPreferredBackend = "GPU",
                appliedPreferredBackend = "GPU",
                preferredBackendApplyResult = "timeout",
                preferredBackendHookReached = false,
                preferredBackendHookSource = "gpu-experimental-watchdog",
                localFailureDiagnosticsText = diagnosticsText,
            )

            localStreamingResponseText = null
            showDelayedLocalRespondingPlaceholder = false
            resetStreamingSpeechState()
            resetStreamingAssistantPlaceholderId(reason = "gpu-watchdog-timeout")
            localInferenceEngineState = LocalInferenceEngineState.ERROR
            isLocalInferenceRunning = false
            localInferenceJob?.cancel()
            localInferenceJob = null
            localGpuWatchdogJob = null

            withContext(Dispatchers.IO) {
                viewModel.insertAssistantMessageAndReturnId(
                    createAssistantMessage(
                        chatId = currentChatId,
                        response = GPU_EXPERIMENTAL_TIMEOUT_MESSAGE,
                        localSourceSummary = diagnosticsText,
                        generationTimeMs = elapsedMs,
                    ),
                )
                localInferenceEngineHolder.resetConversation(
                    chatId = currentChatId,
                    reason = "gpu_watchdog_timeout",
                )
                localInferenceEngineHolder.clear(
                    reason = "gpu_watchdog_timeout_holder_clear",
                    failureStage = "gpu_watchdog_timeout",
                    owner = "ChatScreen.gpuExperimentalWatchdog",
                    appendTrace = { message ->
                        appendLocalReflectionTrace(
                            context = context.applicationContext,
                            message = message,
                        )
                    },
                )
                val holderSnapshotAfterTimeoutCleanup = localInferenceEngineHolder.getDevDiagnosticSnapshot()
                val cleanupDiagnosticsText = buildLocalRouteDiagnosticTrace(
                    stage = "gpu_watchdog_holder_cleanup_finished",
                    context = diagnosticContext,
                    flags = progressFlagsProvider()
                        .copy(
                            failureStage = "gpu_watchdog_timeout",
                            staleCallbackIgnored = true,
                        )
                        .withHeldEngineSnapshot(holderSnapshotAfterTimeoutCleanup),
                    elapsedMs = SystemClock.elapsedRealtime() - runStartedAtMs,
                )
                appendLocalReflectionTrace(
                    context = context.applicationContext,
                    message = cleanupDiagnosticsText,
                )
                latestLocalTraceForDev = latestLocalTraceForDev?.copy(
                    localFailureDiagnosticsText = diagnosticsText + "\n" + cleanupDiagnosticsText,
                    holderInstanceHash = holderSnapshotAfterTimeoutCleanup.holderInstanceHash,
                    heldEngineHash = holderSnapshotAfterTimeoutCleanup.heldEngineHash,
                    holderLastAcquireAction = holderSnapshotAfterTimeoutCleanup.lastAcquireAction,
                    holderLastLifecycleEventReason = holderSnapshotAfterTimeoutCleanup.lastLifecycleEventReason,
                    holderLastLifecycleDecisionAction = holderSnapshotAfterTimeoutCleanup.lastLifecycleDecisionAction,
                    heldEngineRecreateRequestCount = holderSnapshotAfterTimeoutCleanup.recreateRequestCount,
                    holderLastRecreateResult = holderSnapshotAfterTimeoutCleanup.lastRecreateResult,
                    holderLastRecreateReason = holderSnapshotAfterTimeoutCleanup.lastRecreateReason,
                    holderHasHeldEngineBeforeRecreate = holderSnapshotAfterTimeoutCleanup.hasHeldEngineBeforeRecreate,
                    holderHasHeldEngineAfterRecreate = holderSnapshotAfterTimeoutCleanup.hasHeldEngineAfterRecreate,
                    heldEngineLifecycleHistory = holderSnapshotAfterTimeoutCleanup.heldEngineLifecycleHistory,
                    heldEngineDestroyReason = holderSnapshotAfterTimeoutCleanup.heldEngineDestroyReason,
                    heldEngineLastOwner = holderSnapshotAfterTimeoutCleanup.heldEngineLastOwner,
                    heldEngineLastFailureStage = holderSnapshotAfterTimeoutCleanup.heldEngineLastFailureStage,
                    heldEngineSnapshotBeforeDestroy = holderSnapshotAfterTimeoutCleanup.heldEngineSnapshotBeforeDestroy,
                )
            }
        }
    }

    suspend fun resolveLocalPreparingUiState(): LocalInferenceEngineState {
        val hasHeldEngine = localInferenceEngineHolder.getDevDiagnosticSnapshot().heldEngineHash != null
        return if (hasHeldEngine) {
            LocalInferenceEngineState.READY
        } else {
            LocalInferenceEngineState.PREPARING
        }
    }

    fun isTtsSuppressedForAssistant(messageId: Int?): Boolean {
        return messageId != null && suppressedTtsAssistantMessageId == messageId
    }

    suspend fun upsertStreamingAssistantPlaceholder(chatId: Int, response: String): Int? {
        val normalizedResponse = response.trim()
        if (normalizedResponse.isBlank()) return streamingAssistantMessageId

        val existingId = streamingAssistantMessageId
        if (existingId != null && lastPersistedStreamingAssistantText == normalizedResponse) {
            logStreamTrace("STREAM placeholder skip sameText")
            return existingId
        }
        if (existingId == null) {
            val placeholderMessage = createAssistantMessage(
                chatId = chatId,
                response = normalizedResponse,
            )
            val insertedId = viewModel.insertAssistantMessageAndReturnId(placeholderMessage).toInt()
            streamingAssistantMessageId = insertedId
            lastPersistedStreamingAssistantText = normalizedResponse
            streamingSpeechStartedForMessageId = insertedId
            currentSpeakingAssistantMessageId = insertedId
            if (!isTtsSuppressedForAssistant(insertedId)) {
                stopButtonOwnerAssistantMessageId = insertedId
                stopButtonOwnerSetAtMs = SystemClock.elapsedRealtime()
            }
            logStreamTrace("STREAM placeholder insert id=$insertedId")
            return insertedId
        }

        val existingMessage = viewModel.getMessageById(existingId)
        if (existingMessage?.message == normalizedResponse) {
            lastPersistedStreamingAssistantText = normalizedResponse
            logStreamTrace("STREAM placeholder skip sameText")
            return existingId
        }
        val updateTarget = existingMessage?.copy(message = normalizedResponse)
            ?: createAssistantMessage(chatId = chatId, response = normalizedResponse).copy(messageID = existingId)
        viewModel.updateMessage(updateTarget)
        lastPersistedStreamingAssistantText = normalizedResponse
        streamingSpeechStartedForMessageId = existingId
        currentSpeakingAssistantMessageId = existingId
        if (!isTtsSuppressedForAssistant(existingId)) {
            stopButtonOwnerAssistantMessageId = existingId
            stopButtonOwnerSetAtMs = SystemClock.elapsedRealtime()
        }
        logStreamTrace("STREAM placeholder update id=$existingId len=${normalizedResponse.length}")
        return existingId
    }

    suspend fun upsertStreamingAssistantPlaceholderSerialized(chatId: Int, response: String): Int? {
        return streamingAssistantPersistMutex.withLock {
            upsertStreamingAssistantPlaceholder(chatId = chatId, response = response)
        }
    }

    suspend fun finalizeStreamingAssistantMessage(
        chatId: Int,
        response: String,
        latestInferenceStats: InferenceStats? = null,
        localSourceSummary: String? = null,
        imageInputCount: Int? = null,
        generationTimeMs: Long? = null,
    ): Int? {
        // finalize 経路は「保存してよい最終本文」のみを受け取る想定。
        val finalizedResponseForPersist = buildFinalizedStreamingResponseForPersist(
            response = response,
            markdownStreamingMode = markdownStreamingMode,
            onMarkdownRepair = {
                if (BuildConfig.DEBUG) {
                    localStreamingUiMetricsForDev.recordMarkdownRepair()
                }
            },
        )
        if (finalizedResponseForPersist.isBlank()) return streamingAssistantMessageId
        if (finalizedResponseForPersist == "コード生成中…") {
            logStreamTrace("STREAM final skip displayOnlyText")
            return streamingAssistantMessageId
        }
        // finalize後の本文をUI表示系にも反映し、streaming途中本文の残留を防ぐ。
        streamingResponseTextForRender = finalizedResponseForPersist

        val finalPayload = createAssistantMessage(
            chatId = chatId,
            response = finalizedResponseForPersist,
            latestInferenceStats = latestInferenceStats,
            localSourceSummary = localSourceSummary,
            imageInputCount = imageInputCount,
            generationTimeMs = generationTimeMs,
        )
        val existingId = streamingAssistantMessageId
        logStreamTrace("STREAM final path existingId=$existingId")
        if (existingId == null) {
            val insertedId = viewModel.insertAssistantMessageAndReturnId(finalPayload).toInt()
            lastPersistedStreamingAssistantText = finalizedResponseForPersist
            if (latestInferenceStats != null) {
                immediateInferenceStatsByMessageId[insertedId] = latestInferenceStats
            }
            logStreamTrace("STREAM final insert id=$insertedId fallbackNoPlaceholder=true")
            return insertedId
        }

        val existingMessage = viewModel.getMessageById(existingId)
        val updatedMessage = if (existingMessage != null) {
            existingMessage.copy(
                message = finalPayload.message,
                completionTokens = finalPayload.completionTokens,
                generationTimeMs = finalPayload.generationTimeMs,
                generationDurationNs = finalPayload.generationDurationNs,
                evalDurationNs = finalPayload.evalDurationNs,
                loadDurationNs = finalPayload.loadDurationNs,
                promptEvalDurationNs = finalPayload.promptEvalDurationNs,
                modelName = finalPayload.modelName,
                inputTokens = finalPayload.inputTokens,
                totalTokens = finalPayload.totalTokens,
                tokensPerSecond = finalPayload.tokensPerSecond,
                inferenceTimeSec = finalPayload.inferenceTimeSec,
                finishReason = finalPayload.finishReason,
                localSourceSummary = finalPayload.localSourceSummary,
                timeToFirstTokenMs = finalPayload.timeToFirstTokenMs,
                imageInputCount = finalPayload.imageInputCount,
            )
        } else {
            finalPayload.copy(messageID = existingId)
        }
        viewModel.updateMessage(updatedMessage)
        lastPersistedStreamingAssistantText = finalizedResponseForPersist
        if (latestInferenceStats != null) {
            immediateInferenceStatsByMessageId[existingId] = latestInferenceStats
        }
        logStreamTrace("STREAM final update id=$existingId")
        return existingId
    }

    suspend fun finalizeStreamingAssistantMessageSerialized(
        chatId: Int,
        response: String,
        latestInferenceStats: InferenceStats? = null,
        localSourceSummary: String? = null,
        imageInputCount: Int? = null,
        generationTimeMs: Long? = null,
    ): Int? {
        return streamingAssistantPersistMutex.withLock {
            finalizeStreamingAssistantMessage(
                chatId = chatId,
                response = response,
                latestInferenceStats = latestInferenceStats,
                localSourceSummary = localSourceSummary,
                imageInputCount = imageInputCount,
                generationTimeMs = generationTimeMs,
            )
        }
    }

    fun sanitizeTextForTts(text: String): String = sanitizeAssistantTextForTts(text)

    fun sanitizeStreamingTextForTts(text: String): String {
        var insideFencedCodeBlock = false
        val filtered = text
            .lineSequence()
            .map { it.trim() }
            .filterNot { line ->
                if (line.contains("```")) {
                    insideFencedCodeBlock = !insideFencedCodeBlock
                    true
                } else {
                    insideFencedCodeBlock ||
                        line.isBlank() ||
                        line == "コード生成中…" ||
                        line.matches(Regex("^[`*_#>\\-\\s]+$")) ||
                        line.matches(Regex("^[\\p{Punct}\\s]+$")) ||
                        line.matches(Regex(".*[{}();=<>\\[\\]].*"))
                }
            }
            .joinToString(separator = " ")
        return sanitizeTextForTts(filtered)
    }

    suspend fun maybeReleaseHeldEngineForTtsPlayback() {
        val memorySnapshot = withContext(Dispatchers.Default) {
            captureTtsMemorySnapshot(context.applicationContext)
        }
        val decision = decideHeldEngineReleaseForTts(memorySnapshot)
        if (BuildConfig.DEBUG && DEV_UI_DEBUG_MODE) {
            devDebugText = buildTtsMemoryDecisionDebugText(
                snapshot = memorySnapshot,
                decision = decision,
            )
        }
        if (decision.shouldReleaseHeldEngine) {
            withContext(Dispatchers.IO) {
                localInferenceEngineHolder.notifyLifecycleEvent(reason = "tts-playback")
            }
        }
    }

    fun consumeStreamingSentenceAndSpeak(fullText: String) {
        if (!ttsEnabled) return
        if (fullText.contains("```") || fullText.contains("```python") || fullText.contains("```bash")) {
            isStreamingSentencePlaybackActive = false
            streamingSpeechLastConsumedLength = fullText.length
            streamingSpeechStartedForMessageId = null
            viewModel.stopTtsPlayback()
            return
        }
        val targetMessageId = streamingSpeechStartedForMessageId
        if (targetMessageId != null && suppressedTtsAssistantMessageId == targetMessageId) return
        if (fullText.length < streamingSpeechLastConsumedLength) {
            streamingSpeechLastConsumedLength = 0
        }
        streamingSpeechBuffer = fullText
        if (streamingSpeechLastConsumedLength >= fullText.length) return
        val remaining = fullText.substring(streamingSpeechLastConsumedLength)
        val sentenceBreakIndex = findStreamingTtsBreakIndex(remaining)
        if (sentenceBreakIndex < 0) return
        val speakTarget = remaining.substring(0, sentenceBreakIndex + 1)
        val normalized = sanitizeStreamingTextForTts(speakTarget)
        // Streaming sentence TTS uses QUEUE_ADD, so do not drop sentence fragments because
        // the previous queued utterance just ended and the controller is in auto-speak cooldown.
        // Dropping here can skip the final short tail such as "お気軽にどうぞ".
        if (normalized.isNotEmpty()) {
            streamingSpeechStartedForMessageId?.let { messageId ->
                currentSpeakingAssistantMessageId = messageId
                if (!isTtsSuppressedForAssistant(messageId)) {
                    stopButtonOwnerAssistantMessageId = messageId
                    stopButtonOwnerSetAtMs = SystemClock.elapsedRealtime()
                }
            }
            isStreamingSentencePlaybackActive = true
            ttsController.speakQueued(normalized)
        }
        streamingSpeechLastConsumedLength += sentenceBreakIndex + 1
    }

    fun speakStreamingTailIfNeeded(fullText: String) {
        if (!ttsEnabled) return
        if (fullText.contains("```") || fullText.contains("```python") || fullText.contains("```bash")) {
            isStreamingSentencePlaybackActive = false
            streamingSpeechLastConsumedLength = fullText.length
            streamingSpeechStartedForMessageId = null
            viewModel.stopTtsPlayback()
            return
        }
        val targetMessageId = streamingSpeechStartedForMessageId
        if (targetMessageId != null && suppressedTtsAssistantMessageId == targetMessageId) return
        val safeConsumed = streamingSpeechLastConsumedLength.coerceIn(0, fullText.length)
        val remaining = fullText.substring(safeConsumed)
        val normalized = sanitizeStreamingTextForTts(remaining)
        // Tail flush also uses QUEUE_ADD; cooldown must not discard the final unsaid tail.
        if (normalized.isNotEmpty()) {
            streamingSpeechStartedForMessageId?.let { messageId ->
                currentSpeakingAssistantMessageId = messageId
                if (!isTtsSuppressedForAssistant(messageId)) {
                    stopButtonOwnerAssistantMessageId = messageId
                    stopButtonOwnerSetAtMs = SystemClock.elapsedRealtime()
                }
            }
            isStreamingSentencePlaybackActive = true
            ttsController.speakQueued(normalized)
        }
    }

    val effectiveStreamingSentenceTtsEnabled = shouldEnableStreamingSentenceTts(
        ttsEnabled = ttsEnabled,
        devEnableStreamingSentenceTts = devEnableStreamingSentenceTts,
        blockedByNpuStandardRoute = npuStandardRouteStreamingSentenceTtsBlocked,
    )

    LaunchedEffect(
        effectiveStreamingSentenceTtsEnabled,
        isInferenceRunningUi,
        streamingResponseTextForRender,
        streamingResponseText,
    ) {
        if (!effectiveStreamingSentenceTtsEnabled || !isInferenceRunningUi) return@LaunchedEffect
        val fullText = streamingResponseText ?: streamingResponseTextForRender ?: return@LaunchedEffect
        if (fullText.isBlank()) return@LaunchedEffect
        consumeStreamingSentenceAndSpeak(fullText)
    }

    LaunchedEffect(effectiveStreamingSentenceTtsEnabled) {
        if (!effectiveStreamingSentenceTtsEnabled) {
            resetStreamingSpeechState()
        }
    }

    LaunchedEffect(ttsEnabled) {
        if (!ttsEnabled) {
            stopTtsWithCleanup(
                suppressedMessageId = null,
                armTapGuards = false,
            )
        }
    }

    LaunchedEffect(
        isTtsSpeaking,
        isTtsPlaying,
        isInferenceRunningUi,
        isStreamingSentencePlaybackActive,
        stopButtonOwnerAssistantMessageId,
    ) {
        if (isTtsSpeaking || isTtsPlaying) {
            keepTtsTalkingInHeader = true
            return@LaunchedEffect
        }
        val hasActiveTtsContext =
            isStreamingSentencePlaybackActive ||
                stopButtonOwnerAssistantMessageId != null
        if (!isInferenceRunningUi || !hasActiveTtsContext) {
            keepTtsTalkingInHeader = false
            return@LaunchedEffect
        }

        keepTtsTalkingInHeader = true
        delay(TTS_HEADER_TALKING_GRACE_MS)
        if (!isTtsSpeaking && !isTtsPlaying) {
            keepTtsTalkingInHeader = false
        }
    }

    val latestIsInferenceRunningUi by rememberUpdatedState(isInferenceRunningUi)
    val latestIsTtsSpeaking by rememberUpdatedState(isTtsSpeaking)

    DisposableEffect(ttsController) {
        ttsController.setOnPlaybackStateChanged { isPlaying ->
            viewModel.onTtsPlaybackChanged(isPlaying)
            if (isPlaying) {
                pendingStopButtonOwnerClearJob?.cancel()
                pendingStopButtonOwnerClearJob = null
                return@setOnPlaybackStateChanged
            }
            if (!isPlaying) {
                currentSpeakingAssistantMessageId = null
                if (isStreamingSentencePlaybackActive && latestIsInferenceRunningUi) {
                    return@setOnPlaybackStateChanged
                }
                pendingStopButtonOwnerClearJob?.cancel()
                pendingStopButtonOwnerClearJob = coroutineScope.launch {
                    delay(220)
                    if (!latestIsTtsSpeaking && !latestIsInferenceRunningUi && !ttsController.isSpeaking.value) {
                        isStreamingSentencePlaybackActive = false
                        stopButtonOwnerAssistantMessageId = null
                        stopButtonOwnerSetAtMs = null
                    }
                }
            }
        }
        onDispose {
            viewModel.stopTtsPlayback()
            pendingStopButtonOwnerClearJob?.cancel()
            pendingStopButtonOwnerClearJob = null
            pendingReplaySuppressClearJob?.cancel()
            pendingReplaySuppressClearJob = null
            pendingStopUiCooldownClearJob?.cancel()
            pendingStopUiCooldownClearJob = null
            suppressReplayAssistantMessageId = null
            stopUiCooldownAssistantMessageId = null
            currentSpeakingAssistantMessageId = null
            stopButtonOwnerAssistantMessageId = null
            stopButtonOwnerSetAtMs = null
            resetStreamingSpeechState()
            ttsController.shutdown()
        }
    }

    LaunchedEffect(
        isTtsSpeaking,
        isInferenceRunningUi,
        isStreamingSentencePlaybackActive,
        stopButtonOwnerAssistantMessageId,
    ) {
        val ownerMessageId = stopButtonOwnerAssistantMessageId ?: return@LaunchedEffect
        if (isTtsSpeaking || ttsController.isSpeaking.value || isInferenceRunningUi) return@LaunchedEffect

        val ownerAgeMs = SystemClock.elapsedRealtime() - (stopButtonOwnerSetAtMs ?: 0L)
        if (ownerAgeMs < 450L) {
            delay(450L - ownerAgeMs)
        }
        delay(120L)

        if (
            stopButtonOwnerAssistantMessageId == ownerMessageId &&
            !isTtsSpeaking &&
            !ttsController.isSpeaking.value &&
            !isInferenceRunningUi
        ) {
            isStreamingSentencePlaybackActive = false
            currentSpeakingAssistantMessageId = null
            stopButtonOwnerAssistantMessageId = null
            stopButtonOwnerSetAtMs = null
        }
    }

    LaunchedEffect(chatId) {
        pendingStopButtonOwnerClearJob?.cancel()
        pendingStopButtonOwnerClearJob = null
        pendingReplaySuppressClearJob?.cancel()
        pendingReplaySuppressClearJob = null
        pendingStopUiCooldownClearJob?.cancel()
        pendingStopUiCooldownClearJob = null
        suppressReplayAssistantMessageId = null
        stopUiCooldownAssistantMessageId = null
        currentSpeakingAssistantMessageId = null
        stopButtonOwnerAssistantMessageId = null
        stopButtonOwnerSetAtMs = null
        resetStreamingSpeechState()
        resetStreamingAssistantPlaceholderId(reason = "chat-change")
        effectiveChatId?.let { currentChatId ->
            localInferenceEngineHolder.resetConversation(
                chatId = currentChatId,
                reason = "chat-change",
            )
        }
        if (chatId != null) {
            suppressAutoNewChat = false
            suppressChatContentWhileClosingDrawer = false
        }
    }

    LaunchedEffect(pendingNavigateChatId) {
        val targetChatId = pendingNavigateChatId ?: return@LaunchedEffect
        try {
            if (drawerState.isOpen) {
                runCatching { drawerState.close() }
            }
            if (RuntimeFlags.isUiTestRuntime()) {
                yield()
            }
            navHostController.navigate(Routes.chat(targetChatId)) {
                launchSingleTop = true
            }
        } finally {
            pendingNavigateChatId = null
            suppressChatContentWhileClosingDrawer = false
        }
    }

    LaunchedEffect(chatId, chats, pendingNavigateChatId) {
        val resolvedChatId = resolveDefaultChatId(chatId, chats)
        if (pendingNavigateChatId == null) {
            effectiveChatId = resolvedChatId
        }

        if (
            pendingNavigateChatId == null &&
            shouldAutoCreateNewChat(suppressAutoNewChat, resolvedChatId, isCreatingChat)
        ) {
            isCreatingChat = true
            val newChatId = viewModel.insertChatAndReturnId(
                Chat(title = "New chat", titleSource = TitleSource.TEMP)
            )
            effectiveChatId = newChatId
            pendingNavigateChatId = newChatId
        }

        if (resolvedChatId != null) {
            isCreatingChat = false
            suppressAutoNewChat = false
        }
    }

    LaunchedEffect(sortedChats) {
        if (sortedChats.isEmpty()) {
            latestMessagePreviewByChatId = emptyMap()
            return@LaunchedEffect
        }
        val latestMessages = viewModel.getLatestMessagesByChatIds(sortedChats.map { it.chatId })
        latestMessagePreviewByChatId = latestMessages.associate { latestMessage ->
            latestMessage.chatId to formatChatPreview(latestMessage.message)
        }
    }

    LaunchedEffect(availableModels, selectedModel) {
        if (availableModels.size == 1) {
            val singleModelName = availableModels.first().name
            if (selectedModel != singleModelName) {
                viewModel.updateSelectedModel(singleModelName)
            }
        }
    }

    LaunchedEffect(uiState, effectiveChatId) {
        if (toggle) {
            val currentChatId = effectiveChatId
            val guardEpoch = streamingGuardEpoch
            when (uiState) {
                is UiState.Success -> {
                    if (remoteStopRequested) {
                        placeholder = "Enter your prompt..."
                        pendingAssistantImageInputCount = null
                        toggle = false
                        remoteRequestJob = null
                        resetStreamingAssistantPlaceholderId(reason = "stop")
                        viewModel.resetUiState()
                        return@LaunchedEffect
                    }
                    val response = (uiState as UiState.Success).outputText
                    var assistantId: Int? = null
                    if (currentChatId != null) {
                        if (guardEpoch != streamingGuardEpoch) return@LaunchedEffect
                        assistantId = finalizeStreamingAssistantMessageSerialized(
                            chatId = currentChatId,
                            response = response,
                            latestInferenceStats = latestInferenceStats,
                            imageInputCount = pendingAssistantImageInputCount,
                        )
                        if (assistantId != null) {
                            streamingSpeechStartedForMessageId = assistantId
                        }
                    }
                    // Queue TTS before resetting UiState. resetUiState() changes the LaunchedEffect key;
                    // if this coroutine suspends or is cancelled after that, speech scheduled later can
                    // be skipped intermittently even though the assistant text was displayed and saved.
                    var streamingSpeechStateResetForQueuedTail = false
                    // Queue TTS before resetting UiState. resetUiState() changes the LaunchedEffect key;
                    // if this coroutine suspends or is cancelled after that, speech scheduled later can
                    // be skipped intermittently even though the assistant text was displayed and saved.
                    if (effectiveStreamingSentenceTtsEnabled) {
                        maybeReleaseHeldEngineForTtsPlayback()
                        speakStreamingTailIfNeeded(response)
                        // Keep the streaming TTS playback flag active after queueing the final tail.
                        // A second unconditional reset here clears ownership while the queued final
                        // utterance is still pending, which can make the last sentence disappear from
                        // playback on some Android TTS engines.
                        resetStreamingSpeechState(clearPlaybackFlag = false)
                        streamingSpeechStateResetForQueuedTail = true
                    } else if (
                        ttsEnabled &&
                        assistantId != null &&
                        suppressedTtsAssistantMessageId != assistantId &&
                        !ttsController.isInCooldown()
                    ) {
                        sanitizeTextForTts(response).takeIf { it.isNotEmpty() }?.let { speechText ->
                            currentSpeakingAssistantMessageId = assistantId
                            if (!isTtsSuppressedForAssistant(assistantId)) {
                                stopButtonOwnerAssistantMessageId = assistantId
                                stopButtonOwnerSetAtMs = SystemClock.elapsedRealtime()
                            }
                            maybeReleaseHeldEngineForTtsPlayback()
                            ttsController.speak(speechText)
                        }
                    }
                    if (!streamingSpeechStateResetForQueuedTail) {
                        resetStreamingSpeechState()
                    }
                    placeholder = "Enter your prompt..."
                    pendingAssistantImageInputCount = null
                    toggle = false
                    remoteRequestJob = null
                    resetStreamingAssistantPlaceholderId(reason = "success")
                    viewModel.resetUiState()
                }

                is UiState.Error -> {
                    if (remoteStopRequested) {
                        placeholder = "Enter your prompt..."
                        pendingAssistantImageInputCount = null
                        toggle = false
                        remoteRequestJob = null
                        resetStreamingAssistantPlaceholderId(reason = "stop")
                        viewModel.resetUiState()
                        return@LaunchedEffect
                    }
                    if (currentChatId != null) {
                        if (guardEpoch != streamingGuardEpoch) return@LaunchedEffect
                        val assistantId = finalizeStreamingAssistantMessageSerialized(
                            chatId = currentChatId,
                            response = (uiState as UiState.Error).errorMessage,
                        )
                        if (assistantId != null) {
                            streamingSpeechStartedForMessageId = assistantId
                        }
                    }
                    placeholder = "Enter your prompt..."
                    pendingAssistantImageInputCount = null
                    toggle = false
                    remoteRequestJob = null
                    resetStreamingSpeechState()
                    resetStreamingAssistantPlaceholderId(reason = "error")
                    viewModel.resetUiState()
                }

                is UiState.Streaming -> {
                    if (remoteStopRequested) {
                        placeholder = "Enter your prompt..."
                        pendingAssistantImageInputCount = null
                        toggle = false
                        remoteRequestJob = null
                        resetStreamingSpeechState()
                        resetStreamingAssistantPlaceholderId(reason = "stop")
                        viewModel.resetUiState()
                    }
                    // Server streaming is intentionally display-only here.
                    // Persisting every partial chunk races with LaunchedEffect cancellation and can create
                    // multiple assistant rows before the final Success state arrives. The finalized response
                    // is saved exactly once in the UiState.Success branch above.
                }
                else -> Unit
            }
        }
    }

    LaunchedEffect(lamiUiState.lastInteractionTimeMs, lamiUiState.state) {
        val referenceTime = lamiUiState.lastInteractionTimeMs
        val idleTimeoutMs = 6_000L
        delay(idleTimeoutMs)
        viewModel.moveToIdleIfStale(referenceTime, idleTimeoutMs)
    }

    LaunchedEffect(errorMessage, remoteStopRequested) {
        if (errorMessage == null) return@LaunchedEffect
        if (remoteStopRequested && isStopCancellationLikeMessage(errorMessage)) {
            Log.i("ChatScreen", "Suppressed snackbar for remote stop cancellation: $errorMessage")
            return@LaunchedEffect
        }
        snackbarHostState.showSnackbar(
            message = errorMessage,
            duration = SnackbarDuration.Short,
            actionLabel = "ERROR"
        )
    }

    val density = LocalDensity.current
    val configuration = LocalConfiguration.current
    val isLandscape = configuration.orientation == Configuration.ORIENTATION_LANDSCAPE
    val imeBottomPx = WindowInsets.ime.getBottom(density)
    val navBottomPx = WindowInsets.navigationBars.getBottom(density)
    val imeOnlyPx = (imeBottomPx - navBottomPx).coerceAtLeast(0)
    val bottomDp = with(density) { imeOnlyPx.toDp() }

    val createNewChatAndNavigate: () -> Unit = {
        coroutineScope.launch {
            val newChatId = viewModel.insertChatAndReturnId(
                Chat(title = "New chat", titleSource = TitleSource.TEMP)
            )
            effectiveChatId = newChatId
            pendingNavigateChatId = newChatId
        }
    }
    ModalNavigationDrawer(
        drawerState = drawerState,
        drawerContent = {
            // drawerBg は必ず @Composable スコープ（Home() 内）で評価すること
            val drawerBg = MaterialTheme.colorScheme.surface
            val drawerColor = drawerBg

            // Golden ratio based midpoint (1/φ)
            val fadeMidPos = 0.618f
            val fadeMidAlpha = 0.55f
            val fadeMaxAlpha = 0.68f

            // 下端フェード（透明→濃い）
            val bottomFadeStops = arrayOf(
                0.0f to drawerColor.copy(alpha = 0.0f),
                fadeMidPos to drawerColor.copy(alpha = fadeMidAlpha),
                1.0f to drawerColor.copy(alpha = fadeMaxAlpha),
            )

            // 上端フェード（濃い→透明）※ bottom の反転
            val topFadeStops = arrayOf(
                0.0f to drawerColor.copy(alpha = fadeMaxAlpha),
                fadeMidPos to drawerColor.copy(alpha = fadeMidAlpha),
                1.0f to drawerColor.copy(alpha = 0.0f),
            )
            ModalDrawerSheet(
                // 上：Drawer 側のデフォルト safe drawing inset を無効化して検索窓の先頭位置を詰める
                windowInsets = WindowInsets(0, 0, 0, 0),
                drawerContainerColor = drawerBg,
                drawerTonalElevation = 0.dp,
            ) {
                val newChatButtonHeight = 40.dp
                val newChatListTopGap = 0.dp
                // 下端フェード：帯感を減らすため高さを少し詰める（overlayのみでレイアウトは壊さない）
                val drawerBottomFadeHeight = 32.dp
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .fillMaxWidth()
                        // 上：詰めすぎ防止のため最小限の top padding を残す
                        .padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 16.dp)
                ) {
                    DrawerSearchPill(
                        value = chatSearchQuery,
                        onValueChange = { chatSearchQuery = it },
                        onClear = { chatSearchQuery = "" },
                        modifier = Modifier.fillMaxWidth()
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .weight(1f)
                            // 上：検索ピルと New chat ボタンの間隔を 8dp 維持する
                            .padding(top = 8.dp)
                    ) {
                        if (filteredChats.isEmpty()) {
                            Text(
                                text = "該当なし",
                                // 上：New chat ボタン下から空状態メッセージを表示する
                                modifier = Modifier.padding(
                                    start = 16.dp,
                                    end = 16.dp,
                                    top = newChatButtonHeight + newChatListTopGap + 12.dp,
                                    bottom = 12.dp,
                                ),
                                style = MaterialTheme.typography.bodyMedium,
                            )
                        } else {
                            LazyColumn(
                                modifier = Modifier.fillMaxWidth(),
                                contentPadding = PaddingValues(
                                    top = newChatButtonHeight + newChatListTopGap,
                                    // 最終行がフェードに被らないように bottom padding を増やす
                                    bottom = 12.dp + drawerBottomFadeHeight,
                                )
                            ) {
                                items(filteredChats, key = { it.chatId }) { chat ->
                                    val previewText = latestMessagePreviewByChatId[chat.chatId].orEmpty()
                                    TextButton(
                                        onClick = {
                                            suppressChatContentWhileClosingDrawer = true
                                            suppressAutoNewChat = true
                                            pendingNavigateChatId = chat.chatId
                                        },
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(horizontal = 8.dp)
                                    ) {
                                        Column(modifier = Modifier.fillMaxWidth()) {
                                            Text(
                                                text = chat.title,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis,
                                                modifier = Modifier.fillMaxWidth()
                                            )
                                            if (previewText.isNotEmpty()) {
                                                Text(
                                                    text = previewText,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis,
                                                    style = MaterialTheme.typography.bodySmall,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                                    modifier = Modifier.fillMaxWidth()
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // 下端フェードは帯に見えないよう max alpha を落として midpoint を前倒し
                        Box(
                            modifier = Modifier
                                .align(Alignment.BottomStart)
                                .fillMaxWidth()
                                .height(drawerBottomFadeHeight)
                                .drawBehind {
                                    drawRect(
                                        brush = Brush.verticalGradient(
                                            colorStops = bottomFadeStops
                                        )
                                    )
                                }
                        )

                        Box(
                            modifier = Modifier
                                .align(Alignment.TopStart)
                                .fillMaxWidth()
                                // New chat ボタン下端より 8dp 下までフェードを伸ばし、透明側の境目をさらに目立たせない
                                // ※スレッド開始位置は維持（LazyColumn の contentPadding.top は変更しない）
                                .height(newChatButtonHeight + 6.dp)
                                .drawBehind {
                                    drawRect(
                                        brush = Brush.verticalGradient(
                                            colorStops = topFadeStops
                                        )
                                    )
                                }
                        )
                        ElevatedButton(
                            onClick = createNewChatAndNavigate,
                            modifier = Modifier
                                .align(Alignment.TopStart)
                                .zIndex(1f)
                                .height(newChatButtonHeight),
                            elevation = ButtonDefaults.elevatedButtonElevation(
                                defaultElevation = 6.dp,
                                pressedElevation = 8.dp,
                                focusedElevation = 6.dp,
                                hoveredElevation = 6.dp,
                                disabledElevation = 0.dp,
                            )
                        ) {
                            Text("New chat")
                        }
                    }
                }
            }
        }
    ) {
    if (suppressChatContentWhileClosingDrawer) {
        Box(modifier = Modifier.fillMaxSize())
    } else {
        Box(
            modifier = Modifier.fillMaxSize()
        ) {
    Scaffold(
        // 上部の自動 Insets を無効化し、TopAppBar 側でのみ安全領域を制御する
        contentWindowInsets = WindowInsets(left = 0, top = 0, right = 0, bottom = 0),
        topBar = {
            val topAppBarContainerColor = MaterialTheme.colorScheme.surface
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(topAppBarContainerColor)
                    .zIndex(1f)
            ) {
                TopAppBar(
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = topAppBarContainerColor),
                    // TopAppBar の自動 Insets は無効化し、余白発生を防ぐ
                    windowInsets = WindowInsets(left = 0, top = 0, right = 0, bottom = 0),
            title = {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    // Chats 画面とヘッダー位置を揃えるため下余白を統一
                    modifier = Modifier
                        .padding(bottom = 4.dp)
                ) {
                    Box(
                        modifier = Modifier.onGloballyPositioned { coordinates ->
                            measuredSpriteBottomPx = coordinates.positionInRoot().y + coordinates.size.height
                        }
                    ) {
                        HeaderAvatar(
                            baseUrl = baseUrl,
                            selectedModel = selectedModel,
                            lastError = errorMessage,
                            lamiStatus = effectiveLamiStatusForChatUi,
                            lamiState = effectiveLamiHeaderStateForChatUi,
                            availableModels = availableModels,
                            initialAvatarSize = savedChatLamiAvatarSizeDp.dp,
                            minAvatarSize = MIN_CHAT_LAMI_AVATAR_SIZE_DP.dp,
                            maxAvatarSize = MAX_CHAT_LAMI_AVATAR_SIZE_DP.dp,
                            onSelectModel = { modelName ->
                                viewModel.onUserInteraction()
                                viewModel.updateSelectedModel(modelName)
                            },
                            onNavigateSettings = { navHostController.navigate(Routes.SETTINGS) },
                            selectedInferenceTarget = selectedInferenceTarget,
                            onSelectInferenceTarget = { target ->
                                selectedInferenceTarget = target
                                coroutineScope.launch {
                                    settingsPreferences.saveInferenceTarget(target)
                                }
                            },
                            localInferenceEngineState = localInferenceEngineState,
                            debugOverlayEnabled = false,
                            syncEpochMs = animationEpochMs,
                            openControlRequestKey = openLamiControlRequestKey,
                        )
                    }
                    // ヘッダー内の最小間隔だけ確保して左余白を増やさない
                    Spacer(modifier = Modifier.size(2.dp))
                        LamiHeaderStatus(
                            baseUrl = baseUrl,
                            selectedModel = selectedModel,
                            lastError = errorMessage,
                        lamiStatus = effectiveLamiStatusForChatUi,
                        lamiState = effectiveLamiHeaderStateForChatUi,
                        availableModels = availableModels,
                        onSelectModel = { modelName ->
                            viewModel.onUserInteraction()
                            viewModel.updateSelectedModel(modelName)
                            },
                            onNavigateSettings = { navHostController.navigate(Routes.SETTINGS) },
                            selectedInferenceTarget = selectedInferenceTarget,
                            localBaseModelDisplayName = selectedLocalModelDisplayName,
                            onSelectInferenceTarget = { target ->
                                selectedInferenceTarget = target
                                coroutineScope.launch {
                                    settingsPreferences.saveInferenceTarget(target)
                                }
                            },
                            localInferenceEngineState = localInferenceEngineState,
                            debugOverlayEnabled = false,
                            syncEpochMs = animationEpochMs,
                            initialAvatarSize = savedChatLamiAvatarSizeDp.dp,
                        minAvatarSize = MIN_CHAT_LAMI_AVATAR_SIZE_DP.dp,
                        maxAvatarSize = MAX_CHAT_LAMI_AVATAR_SIZE_DP.dp,
                        // title 内で HeaderAvatar を表示しているため二重表示を防ぐ
                        showAvatar = false,
                        onOpenControl = {
                            viewModel.onUserInteraction()
                            openLamiControlRequestKey += 1
                        },
                        statusTitleOverride = headerStatusTitleOverride,
                    )
                }
            },
            actions = {
                IconButton(onClick = {
                    viewModel.onUserInteraction()
                    coroutineScope.launch { drawerState.open() }
                }) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.List,
                        contentDescription = "チャット一覧",
                        modifier = Modifier.size(26.dp)
                    )
                }
                IconButton(onClick = {
                    viewModel.onUserInteraction()
                    navHostController.navigate(Routes.SETTINGS)
                }) {
                    Icon(
                        painter = painterResource(R.drawable.settings),
                        contentDescription = "設定",
                        modifier = Modifier.size(26.dp)
                    )
                }
                    },
                )
            }
        }, bottomBar = {
        val textMeasurer = rememberTextMeasurer()
        val maxComposerLines = 6
        val composerTextStyle = MaterialTheme.typography.bodyLarge.copy(
            fontSize = 15.sp,
            fontWeight = FontWeight.Normal,
            fontSynthesis = FontSynthesis.None,
            fontFamily = FontFamily.Default,
            color = MaterialTheme.colorScheme.onSurface
        )
        val overlayBase = MaterialTheme.colorScheme.background
        val composerBottomGradientEnabled = shouldEnableComposerBottomGradient(isLandscape)

        Column(
            modifier = Modifier
                .fillMaxWidth()
                // IME 分のみを下余白に反映し、非表示時の余白は 0dp にする
                .padding(bottom = bottomDp)
                .onGloballyPositioned { coordinates ->
                    overlayRootTopY = coordinates.positionInRoot().y
                }
                .let { modifier ->
                    if (composerBottomGradientEnabled) {
                        modifier.drawWithContent {
                            val localTop = (measuredComposerTopY - overlayRootTopY).coerceAtLeast(0f)
                            val overlayHeight = (size.height - localTop).coerceAtLeast(1f)
                            drawRect(
                                brush = Brush.verticalGradient(
                                    colorStops = arrayOf(
                                        0.0f to overlayBase.copy(alpha = 0.0f),
                                        0.5f to overlayBase.copy(alpha = 0.5f),
                                        1.0f to overlayBase.copy(alpha = 1.0f)
                                    ),
                                    startY = localTop,
                                    endY = localTop + overlayHeight
                                ),
                                topLeft = Offset(0f, localTop),
                                size = Size(size.width, overlayHeight)
                            )

                            drawContent()
                        }
                    } else {
                        modifier
                    }
                }
        ) {
            BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
                Box {
                    BoxWithConstraints(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 17.dp)
                    ) {
                    // Surface 内の実幅から固定要素（左右 Spacer/左右ボタン）と TextField 内部余白を差し引く
                    val availableTextWidthDp =
                        maxWidth - 0.dp - ComposerButtonSize - ComposerButtonSize - 0.dp - (4.dp * 2)
                    val availableTextWidthPx = with(density) {
                        availableTextWidthDp.coerceAtLeast(0.dp).toPx().roundToInt().coerceAtLeast(1)
                    }
                    val measuredLines by remember(userPrompt, availableTextWidthPx, composerTextStyle) {
                        derivedStateOf {
                            if (userPrompt.isEmpty()) {
                                1
                            } else {
                                textMeasurer.measure(
                                    text = AnnotatedString(userPrompt),
                                    style = composerTextStyle,
                                    softWrap = true,
                                    maxLines = maxComposerLines,
                                    overflow = TextOverflow.Clip,
                                    constraints = Constraints(maxWidth = availableTextWidthPx)
                                ).lineCount.coerceIn(1, maxComposerLines)
                            }
                        }
                    }
                    val composerShape = RoundedCornerShape(ComposerPillRadius)
                    Surface(
                        shape = composerShape,
                        color = MaterialTheme.colorScheme.surface,
                        border = androidx.compose.foundation.BorderStroke(
                            width = 1.dp,
                            color = MaterialTheme.colorScheme.primary
                        ),
                        modifier = Modifier
                            .fillMaxWidth()
                            .zIndex(composerInputLayerZIndex())
                            .onGloballyPositioned { coordinates ->
                                measuredComposerTopY = coordinates.positionInRoot().y
                            }
                    ) {
                        Box(modifier = Modifier.fillMaxWidth()) {
                            Column(modifier = Modifier.fillMaxWidth()) {
                                if (selectedImageUris.isNotEmpty()) {
                                    AttachmentPreviewRow(
                                        uris = selectedImageUris,
                                        onOpen = { index ->
                                            composerViewerUriStrings = selectedImageUriStrings.toList()
                                            composerViewerInitialIndex = index
                                        },
                                        onRemoveAt = { removeIndex ->
                                            selectedImageUriStrings = selectedImageUriStrings.filterIndexed { index, _ ->
                                                index != removeIndex
                                            }
                                        },
                                        inComposer = true,
                                    )
                                    // サムネイルと入力行を視認分離する最小限の余白
                                    Spacer(modifier = Modifier.height(2.dp))
                                }

                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .heightIn(min = ComposerMinHeight),
                                    verticalAlignment = Alignment.Bottom
                                ) {
                                    // 左ボタンを外側へ寄せるための最小余白
                                    Spacer(modifier = Modifier.width(0.dp))

                                    IconButton(
                                        onClick = { attachSheetOpen = true },
                                        modifier = Modifier
                                            .size(ComposerButtonSize)
                                            .align(Alignment.Bottom)
                                            .clip(CircleShape)
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(ComposerButtonVisualSize)
                                                .clip(CircleShape)
                                                .background(Color.LightGray.copy(alpha = 0.25f)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Icon(
                                                imageVector = Icons.Filled.Add,
                                                contentDescription = "Tools",
                                                modifier = Modifier.size(ComposerButtonIconVisualSize)
                                            )
                                        }
                                    }

                                    BasicTextField(
                                        value = userPrompt,
                                        onValueChange = { newValue ->
                                            userPrompt = newValue
                                            viewModel.onUserInteraction()
                                        },
                                        modifier = Modifier
                                            .weight(1f)
                                            .align(Alignment.CenterVertically)
                                            .heightIn(min = 44.dp, max = 180.dp),
                                        singleLine = false,
                                        maxLines = maxComposerLines,
                                        textStyle = composerTextStyle,
                                        interactionSource = interactionSource,
                                        cursorBrush = SolidColor(MaterialTheme.colorScheme.primary),
                                        decorationBox = { innerTextField ->
                                            OutlinedTextFieldDefaults.DecorationBox(
                                                value = userPrompt,
                                                innerTextField = innerTextField,
                                                enabled = true,
                                                singleLine = false,
                                                visualTransformation = VisualTransformation.None,
                                                interactionSource = interactionSource,
                                                placeholder = {
                                                    Text(
                                                        placeholder,
                                                        style = LamiTypographyTokens.chatPlaceholder(),
                                                    )
                                                },
                                                colors = OutlinedTextFieldDefaults.colors(
                                                    unfocusedBorderColor = Color.Transparent,
                                                    focusedBorderColor = Color.Transparent,
                                                    unfocusedContainerColor = Color.Transparent,
                                                    focusedContainerColor = Color.Transparent
                                                ),
                                                contentPadding = PaddingValues(horizontal = 4.dp, vertical = 10.dp)
                                            )
                                        }
                                    )

                                    IconButton(
                                        enabled = isComposerStopActive || resolveChatSendAvailability(
                                            selectedInferenceTarget = selectedInferenceTarget,
                                            selectedServerModel = selectedModel,
                                            selectedLocalModelPath = selectedLocalModelFilePath,
                                            serverUrl = baseUrl,
                                            hasPromptText = userPrompt.isNotEmpty(),
                                            hasImageInput = selectedImageUriStrings.isNotEmpty(),
                                            isInferenceRunning = isInferenceRunningUi,
                                        ).enabled,
                                        onClick = {
                                            viewModel.onUserInteraction()
                                            if (!isInferenceRunningUi && isComposerStopActive) {
                                                stopTtsWithCleanup(
                                                    suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                        ?: currentSpeakingAssistantMessageId
                                                        ?: streamingSpeechStartedForMessageId,
                                                    armTapGuards = true,
                                                )
                                                return@IconButton
                                            }
                                                if (isInferenceRunningUi) {
                                                    if (isLocalRunningRaw) {
                                                        localStopRequested = true
                                                        localGpuWatchdogJob?.cancel()
                                                        localGpuWatchdogJob = null
                                                        localInferenceJob?.cancel()
                                                        localInferenceJob = null
                                                        effectiveChatId?.let { currentChatId ->
                                                            coroutineScope.launch {
                                                                localInferenceEngineHolder.resetConversation(
                                                                chatId = currentChatId,
                                                                reason = "stop",
                                                            )
                                                        }
                                                    }
                                                    localStreamingResponseText = null
                                                    didReceiveRealLocalPartial = false
                                                    realLocalPartialChunkCount = 0
                                                    isLocalInferenceRunning = false
                                                    stopTtsWithCleanup(
                                                        suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                            ?: currentSpeakingAssistantMessageId
                                                            ?: streamingSpeechStartedForMessageId,
                                                        armTapGuards = false,
                                                    )
                                                    resetStreamingAssistantPlaceholderId(reason = "stop")
                                                    return@IconButton
                                                }
                                                if (isServerRunningRaw) {
                                                    remoteStopRequested = true
                                                    remoteRequestJob?.cancel()
                                                    viewModel.cancelRemoteRequest()
                                                    remoteRequestJob = null
                                                    pendingAssistantImageInputCount = null
                                                    placeholder = "Enter your prompt..."
                                                    toggle = false
                                                    stopTtsWithCleanup(
                                                        suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                            ?: currentSpeakingAssistantMessageId
                                                            ?: streamingSpeechStartedForMessageId,
                                                        armTapGuards = false,
                                                    )
                                                    resetStreamingAssistantPlaceholderId(reason = "stop")
                                                    viewModel.resetUiState()
                                                    return@IconButton
                                                }
                                            }
                                            val sendAvailability = resolveChatSendAvailability(
                                                selectedInferenceTarget = selectedInferenceTarget,
                                                selectedServerModel = selectedModel,
                                                selectedLocalModelPath = selectedLocalModelFilePath,
                                                serverUrl = baseUrl,
                                                hasPromptText = userPrompt.isNotEmpty(),
                                                hasImageInput = selectedImageUriStrings.isNotEmpty(),
                                                isInferenceRunning = false,
                                            )
                                            if (!sendAvailability.enabled) {
                                                coroutineScope.launch {
                                                    snackbarHostState.currentSnackbarData?.dismiss()
                                                    snackbarHostState.showSnackbar(
                                                        message = chatSendBlockedSnackbarMessage(sendAvailability.blockedReason),
                                                        duration = SnackbarDuration.Short
                                                    )
                                                }
                                                return@IconButton
                                            }

                                            Log.i("ChatScreen", "send entry selectedInferenceTarget=$selectedInferenceTarget")
                                            when (selectedInferenceTarget) {
                                                InferenceTarget.SERVER -> {
                                                    val currentChatId = effectiveChatId
                                                    if (currentChatId != null) {
                                                        val requestPrompt = userPrompt
                                                        val requestAttachmentUris = selectedImageUris
                                                        pendingAssistantImageInputCount = requestAttachmentUris.size
                                                        if (requestPrompt.isNotEmpty() || requestAttachmentUris.isNotEmpty()) {
                                                            placeholder = "I'm thinking ... "
                                                            toggle = true
                                                        }
                                                        stopTtsWithCleanup(
                                                            suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                                ?: currentSpeakingAssistantMessageId
                                                                ?: streamingSpeechStartedForMessageId,
                                                            armTapGuards = false,
                                                        )
                                                        prompt = requestPrompt
                                                        remoteStopRequested = false
                                                        remoteRequestJob = coroutineScope.launch {
                                                            try {
                                                                viewModel.sendPrompt(
                                                                    prompt = requestPrompt,
                                                                    model = selectedModel,
                                                                    attachmentUris = requestAttachmentUris,
                                                                    context = context.applicationContext,
                                                                    onAttachmentPrepared = { savedAttachmentUriStrings ->
                                                                        if (requestPrompt.isNotEmpty() || !savedAttachmentUriStrings.isNullOrEmpty()) {
                                                                            val attachmentJson = savedAttachmentUriStrings
                                                                                ?.takeIf { it.isNotEmpty() }
                                                                                ?.toAttachmentUriStringsJson()
                                                                            viewModel.insert(
                                                                                Message(
                                                                                    chatId = currentChatId,
                                                                                    message = requestPrompt,
                                                                                    isSendbyMe = true,
                                                                                    attachmentUriString = savedAttachmentUriStrings?.singleOrNull(),
                                                                                    attachmentUriStringsJson = attachmentJson,
                                                                                )
                                                                            )
                                                                        }
                                                                    },
                                                                )
                                                            } finally {
                                                                remoteRequestJob = null
                                                            }
                                                        }
                                                        prompt = ""
                                                        userPrompt = ""
                                                        selectedImageUriStrings = emptyList()
                                                    } else {
                                                        placeholder = "Setting up a new chat ..."
                                                    }
                                                }

                                                InferenceTarget.LOCAL -> {
                                                    val existingLocalJob = localInferenceJob
                                                    when (resolveExistingLocalGenerationJobPolicy(
                                                        isLocalInferenceRunning = isLocalInferenceRunning,
                                                        existingJobActive = existingLocalJob?.isActive == true,
                                                    )) {
                                                        ExistingLocalGenerationJobPolicy.CANCEL_STALE_AND_WAIT -> {
                                                            cancelStaleLocalGeneration(reason = "stale-local-generation-cancel-before-new-run")
                                                            coroutineScope.launch {
                                                                snackbarHostState.currentSnackbarData?.dismiss()
                                                                snackbarHostState.showSnackbar(
                                                                    message = "前回のローカル生成を停止しました。もう一度送信してください。",
                                                                    duration = SnackbarDuration.Short,
                                                                )
                                                            }
                                                            return@IconButton
                                                        }
                                                        ExistingLocalGenerationJobPolicy.ALREADY_RUNNING -> return@IconButton
                                                        ExistingLocalGenerationJobPolicy.START_NEW -> Unit
                                                    }
                                                    if (selectedImageUriStrings.isNotEmpty()) {
                                                        coroutineScope.launch {
                                                            snackbarHostState.currentSnackbarData?.dismiss()
                                                            snackbarHostState.showSnackbar(
                                                                message = "ローカル推論では画像入力はまだ未対応です",
                                                                duration = SnackbarDuration.Short,
                                                            )
                                                        }
                                                        return@IconButton
                                                    }
                                                    val requestPrompt = userPrompt
                                                    if (requestPrompt.isBlank()) return@IconButton
                                                    val localSendTapElapsedMs = SystemClock.elapsedRealtime()
                                                    lastLocalSendTapElapsedMs = localSendTapElapsedMs
                                                    lastLocalSendPromptForTrace = requestPrompt
                                                    debugLocalUiTrace(
                                                        label = "SEND_TAP",
                                                        extra = "t=$localSendTapElapsedMs promptLength=${requestPrompt.length} chatId=$effectiveChatId",
                                                    )
                                                    val blockedDecision = runUnlessConversationBlockedBySafetyGuard(
                                                        chatId = effectiveChatId,
                                                        blockedConversations = safetyGuardBlockedConversations,
                                                    ) {
                                                        Unit
                                                    }
                                                    if (!blockedDecision.generated) {
                                                        cancelStaleLocalGeneration(reason = "safety-guard-blocked-conversation")
                                                        recycleLocalEngineAfterSafetyGuard(chatId = effectiveChatId)
                                                        showSafetyGuardBlockedConversationMessage(chatId = effectiveChatId)
                                                        devDebugText = listOf(
                                                            "guard_state=blocked",
                                                            "last_safety_stage=$MEMORY_STAGE_SAFETY_GUARD_TRIGGERED",
                                                            "generate_invoked=false",
                                                            "message=$SAFETY_GUARD_BLOCKED_USER_MESSAGE",
                                                        ).joinToString("\n")
                                                        return@IconButton
                                                    }
                                                    val immediateLocalChatId = effectiveChatId
                                                    val immediateLocalUserInsertJob = immediateLocalChatId?.let { chatId ->
                                                        coroutineScope.launch(Dispatchers.IO) {
                                                            Log.i(
                                                                "ChatScreen",
                                                                "[LOCAL_UI] DB_INSERT_START dt=${SystemClock.elapsedRealtime() - localSendTapElapsedMs}ms chatId=$chatId promptLength=${requestPrompt.length}",
                                                            )
                                                            viewModel.insert(
                                                                Message(
                                                                    chatId = chatId,
                                                                    message = requestPrompt,
                                                                    isSendbyMe = true,
                                                                )
                                                            )
                                                            Log.i(
                                                                "ChatScreen",
                                                                "[LOCAL_UI] DB_INSERT_DONE dt=${SystemClock.elapsedRealtime() - localSendTapElapsedMs}ms chatId=$chatId promptLength=${requestPrompt.length}",
                                                            )
                                                        }
                                                    }
                                                    // Show a Compose-only user row immediately while Room/Flow/Compose warms up.
                                                    // The render guard hides this pending row as soon as the persisted DB row matches,
                                                    // so it avoids the first-send lag without duplicating the message.
                                                    pendingLocalUserMessageText = requestPrompt
                                                    suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = true
                                                    prompt = ""
                                                    userPrompt = ""
                                                    selectedImageUriStrings = emptyList()
                                                    showDelayedLocalRespondingPlaceholder = false
                                                    localInferenceEngineState = LocalInferenceEngineState.READY
                                                    localStopRequested = false
                                                    debugLocalUiTrace(
                                                        label = "COMPOSER_CLEARED",
                                                        extra = "dt=${SystemClock.elapsedRealtime() - localSendTapElapsedMs}ms chatId=$immediateLocalChatId",
                                                    )
                                                    coroutineScope.launch localSendLaunch@ {
                                                        // Give Compose at least a few frames to render the cleared composer
                                                        // and the user message before local/NPU route setup can occupy the UI.
                                                        delay(50)
                                                        debugLocalUiTrace(
                                                            label = "ROUTE_DEFERRED_START",
                                                            extra = "dt=${SystemClock.elapsedRealtime() - localSendTapElapsedMs}ms chatId=$immediateLocalChatId",
                                                        )
                                                    val rawNpuStandardRouteRequested =
                                                        NpuStandardRouteS1GateConfig.isEnabledForMode(npuStandardRouteMode)
                                                    val effectiveNpuStandardRouteRequested =
                                                        NpuStandardRouteS1GateConfig.isEnabledForMode(effectiveNpuStandardRouteMode)
                                                    val normalChatNativeRouteBlocked =
                                                        rawNpuStandardRouteRequested && !effectiveNpuStandardRouteRequested
                                                    val normalChatNativeRouteBlockedReason =
                                                        if (normalChatNativeRouteBlocked) {
                                                            NPU_S1_REPEATED_RUN_BLOCKED_SELECTED_BACKEND_NOT_NPU
                                                        } else {
                                                            "none"
                                                        }
                                                    val shouldEnterNpuS1ForRequest = shouldEnterNpuStandardRouteS1(
                                                        enabled = effectiveNpuStandardRouteRequested,
                                                        selectedInferenceTarget = selectedInferenceTarget,
                                                        hasImageInput = selectedImageUriStrings.isNotEmpty(),
                                                        requestPrompt = requestPrompt,
                                                    )
                                                    val localRouteEnteredAfterNpuDecision = shouldEnterLocalLiteRtRouteAfterNpuS1Decision(
                                                        shouldEnterNpuS1 = shouldEnterNpuS1ForRequest,
                                                        selectedInferenceTarget = selectedInferenceTarget,
                                                        hasImageInput = selectedImageUriStrings.isNotEmpty(),
                                                        requestPrompt = requestPrompt,
                                                    )
                                                    val localRouteDiagnosticContext = buildLocalRouteDiagnosticContext(
                                                        selectedModelName = selectedLocalModelDisplayName ?: selectedModel,
                                                        selectedModelFile = selectedLocalModelFilePath,
                                                        selectedModelSlot = selectedLocalModelSlot.diagnosticName,
                                                        npuPreviewModelConfigured = !localBaseModelFilePath.isNullOrBlank(),
                                                        genericFallbackModelConfigured = !localGenericModelFilePath.isNullOrBlank(),
                                                        preferredBackend = preferredBackendDryRunSetting.name,
                                                        npuStandardRouteMode = npuStandardRouteMode.name,
                                                        effectiveNpuStandardRouteMode = effectiveNpuStandardRouteMode.name,
                                                        shouldEnterNpuS1 = shouldEnterNpuS1ForRequest,
                                                        localRouteEntered = localRouteEnteredAfterNpuDecision,
                                                        normalChatNativeRouteBlocked = normalChatNativeRouteBlocked,
                                                        blockedReason = normalChatNativeRouteBlockedReason,
                                                        nativeLibraryDir = context.applicationInfo.nativeLibraryDir,
                                                    )
                                                    appendLocalReflectionTrace(
                                                        context = context.applicationContext,
                                                        message = buildLocalRouteDiagnosticTrace(
                                                            stage = "route_decision",
                                                            context = localRouteDiagnosticContext,
                                                        ),
                                                    )
                                                    if (shouldEnterNpuS1ForRequest) {
                                                        val npuModelEligibility = resolveNpuStandardRouteS1ModelEligibility(
                                                            selectedModelName = localBaseModelDisplayName ?: selectedModel,
                                                            selectedModelFile = localBaseModelFilePath,
                                                        )
                                                        val immediateNpuSendUiUpdate = prepareImmediateNpuSendUiStateUpdate(requestPrompt)
                                                        prompt = immediateNpuSendUiUpdate.prompt
                                                        userPrompt = immediateNpuSendUiUpdate.userPrompt
                                                        selectedImageUriStrings = immediateNpuSendUiUpdate.selectedImageUriStrings
                                                        npuStandardRouteS1DisplayText = null
                                                        npuStandardRoutePhaseUiAppendText = null
                                                        npuStandardRouteS1FallbackText = null
                                                        npuStandardRouteS4PseudoStreamingText = null
                                                        npuStandardRouteS4PseudoStreamingActive = false
                                                        npuStandardRouteStreamingSentenceTtsBlocked = false
                                                        npuStandardRouteDevDiagnosticsExpanded = false
                                                        suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = true
                                                        showDelayedLocalRespondingPlaceholder = false
                                                        localInferenceEngineState = LocalInferenceEngineState.READY
                                                        localStopRequested = false
                                                        isLocalInferenceRunning = true
                                                        stopTtsWithCleanup(
                                                            suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                                ?: currentSpeakingAssistantMessageId
                                                                ?: streamingSpeechStartedForMessageId,
                                                            armTapGuards = false,
                                                        )
                                                        localInferenceJob = coroutineScope.launch {
                                                            var resolvedNpuChatId: Int? = null
                                                            var npuS1DecodeStartedAtMs: Long? = null
                                                            val npuS1MemorySnapshots = mutableListOf<MemorySnapshot>()
                                                            fun recordNpuS1MemorySnapshot(stage: String) {
                                                                npuS1MemorySnapshots += captureLocalMemorySnapshot(
                                                                    context = context.applicationContext,
                                                                    stage = stage,
                                                                )
                                                            }
                                                            fun appendNpuS1MemoryDiagnostics(displayText: String): String =
                                                                appendMemoryDiagnosticsForDev(
                                                                    text = displayText,
                                                                    snapshots = npuS1MemorySnapshots,
                                                                )
                                                            try {
                                                                recordNpuS1MemorySnapshot(MEMORY_STAGE_BEFORE_GENERATE)
                                                                recordNpuS1MemorySnapshot(MEMORY_STAGE_AFTER_PROMPT_BUILD)
                                                                val npuRealPromptTrace: (String) -> Unit = { message ->
                                                                    logStreamTrace(message)
                                                                }
                                                                val immediateNpuRun = runNpuInferenceAfterImmediateUserMessage(
                                                                    requestPrompt = requestPrompt,
                                                                    currentChatId = effectiveChatId,
                                                                    createChat = {
                                                                        isCreatingChat = true
                                                                        try {
                                                                            withContext(Dispatchers.IO) {
                                                                                viewModel.insertChatAndReturnId(
                                                                                    Chat(title = "New chat", titleSource = TitleSource.TEMP)
                                                                                )
                                                                            }
                                                                        } finally {
                                                                            isCreatingChat = false
                                                                        }
                                                                    },
                                                                    onChatCreated = { newChatId ->
                                                                        effectiveChatId = newChatId
                                                                        pendingNavigateChatId = newChatId
                                                                    },
                                                                    insertUserMessage = { chatId, promptText ->
                                                                        if (immediateLocalChatId == chatId && immediateLocalUserInsertJob != null) {
                                                                            immediateLocalUserInsertJob.join()
                                                                        } else {
                                                                            withContext(Dispatchers.IO) {
                                                                                viewModel.insertAssistantMessageAndReturnId(
                                                                                    Message(
                                                                                        chatId = chatId,
                                                                                        message = promptText,
                                                                                        isSendbyMe = true,
                                                                                    )
                                                                                )
                                                                            }
                                                                        }
                                                                        pendingLocalUserMessageText = null
                                                                    },
                                                                    runInference = {
                                                                        npuS1DecodeStartedAtMs = SystemClock.elapsedRealtime()
                                                                        recordNpuS1MemorySnapshot(MEMORY_STAGE_BEFORE_ENGINE_CALL)
                                                                        npuRealPromptTrace(
                                                                            buildNpuRealPromptHandoffTrace(
                                                                                stage = "chat",
                                                                                userPrompt = requestPrompt,
                                                                            ),
                                                                        )
                                                                        if (npuStandardRouteRolloutSelection.completedRouteDisabledByProperty) {
                                                                            buildNpuStandardRouteKillSwitchBlockedResult(
                                                                                maxOutputTokens = npuStandardRouteMaxOutputTokens,
                                                                                selectedModelName = npuModelEligibility.selectedModelName,
                                                                                selectedModelFile = npuModelEligibility.selectedModelFile,
                                                                                npuModelEligible = npuModelEligibility.npuModelEligible,
                                                                                inputPrompt = requestPrompt,
                                                                            )
                                                                        } else if (!npuModelEligibility.npuModelEligible) {
                                                                            buildNpuStandardRouteS1ModelNotCompatibleResult(
                                                                                eligibility = npuModelEligibility,
                                                                                maxOutputTokens = npuStandardRouteMaxOutputTokens,
                                                                            )
                                                                        } else {
                                                                            NpuStandardRouteS1AppHistory.recordStarted(
                                                                                context = context.applicationContext,
                                                                                prompt = requestPrompt,
                                                                                selectedModelFile = localBaseModelFilePath,
                                                                            )
                                                                            withContext(Dispatchers.Default) {
                                                                                NpuStandardRouteS1Bridge(
                                                                                    mode = effectiveNpuStandardRouteMode,
                                                                                    trace = npuRealPromptTrace,
                                                                                )
                                                                                    .run(
                                                                                        userPrompt = requestPrompt,
                                                                                        maxOutputTokens = npuStandardRouteMaxOutputTokens,
                                                                                    )
                                                                            }
                                                                        }
                                                                    },
                                                                )
                                                                val currentChatId = immediateNpuRun.chatId
                                                                resolvedNpuChatId = currentChatId
                                                                val s1Result = immediateNpuRun.result.withTiming(
                                                                    buildNpuStandardRouteS1UiTiming(
                                                                        result = immediateNpuRun.result,
                                                                        decodeStartedAtMs = npuS1DecodeStartedAtMs,
                                                                    ),
                                                                )
                                                                if (
                                                                    npuModelEligibility.npuModelEligible &&
                                                                    !npuStandardRouteRolloutSelection.completedRouteDisabledByProperty
                                                                ) {
                                                                    NpuStandardRouteS1AppHistory.recordFinished(
                                                                        context = context.applicationContext,
                                                                        result = s1Result,
                                                                    )
                                                                }
                                                                recordNpuS1MemorySnapshot(
                                                                    if (s1Result.status == NpuStandardRouteS1Contract.STATUS_SUCCESS) {
                                                                        MEMORY_STAGE_GENERATION_FINISHED
                                                                    } else {
                                                                        MEMORY_STAGE_GENERATION_FAILED
                                                                    },
                                                                )
                                                                recordNpuS1MemorySnapshot(MEMORY_STAGE_AFTER_RUNNER_DISPOSE)
                                                        npuRealPromptTrace(
                                                            buildNpuRealPromptResultTrace(
                                                                status = s1Result.status,
                                                                reason = s1Result.reason,
                                                                maxOutputTokens = s1Result.selection.effectiveMaxOutputTokens,
                                                                rawOutput = s1Result.rawOutput,
                                                                sanitizedOutput = s1Result.sanitizedOutput,
                                                                qualityClassification = s1Result.qualityClassification,
                                                                runDecodeReached = s1Result.runDecodeReached,
                                                                fallbackUsed = s1Result.fallbackUsed,
                                                                timeout = s1Result.timeout,
                                                                freshCrash = s1Result.freshCrash,
                                                                selectedModelName = s1Result.selectedModelName,
                                                                selectedModelFile = s1Result.selectedModelFile,
                                                                npuModelEligible = s1Result.npuModelEligible,
                                                                timing = s1Result.timing,
                                                            ),
                                                        )
                                                        val npuStandardRoutePhaseDiagnostics =
                                                            buildNpuStandardRoutePhase1DiagnosticsForNpuS1Result(
                                                                result = s1Result,
                                                                backendDiagnostics = npuS1BackendDiagnosticsForResult(
                                                                    result = s1Result,
                                                                    preferredBackendSetting = preferredBackendDryRunSetting,
                                                                    npuStandardRouteMode = effectiveNpuStandardRouteMode,
                                                                ),
                                                                rolloutSelection = npuStandardRouteRolloutSelection,
                                                            )
                                                        val npuStandardRoutePhaseGateActive =
                                                            npuStandardRoutePhaseDiagnostics.isNotEmpty()
                                                        val npuStandardRouteUiAppendAllowed =
                                                            npuStandardRoutePhaseDiagnostics[
                                                                "npu_standard_route_ui_append_allowed"
                                                            ] == "true"
                                                        val npuStandardRouteDbSaveAllowed =
                                                            !npuStandardRoutePhaseGateActive ||
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_db_save_allowed"
                                                                ] == "true"
                                                        val npuStandardRouteMarkdownAllowed =
                                                            !npuStandardRoutePhaseGateActive ||
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_markdown_allowed"
                                                                ] == "true"
                                                        val npuStandardRouteStreamingAllowed =
                                                            !npuStandardRoutePhaseGateActive ||
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_streaming_allowed"
                                                                ] == "true"
                                                        val npuStandardRouteTtsAllowed =
                                                            !npuStandardRoutePhaseGateActive ||
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_tts_allowed"
                                                                ] == "true"
                                                        val npuStandardRouteLegacyS5TtsAllowed =
                                                            npuStandardRouteTtsAllowed && !npuStandardRoutePhaseGateActive
                                                        val npuStandardRouteLegacyDbSaveAllowed =
                                                            npuStandardRouteDbSaveAllowed && !npuStandardRoutePhaseGateActive
                                                        val s1RouteDisplayText = if (npuStandardRouteUiAppendAllowed) {
                                                            s1Result.actualDisplayText
                                                        } else {
                                                            s1Result.displayText
                                                        }
                                                        val s1DisplayTextForDev = appendNpuS1MemoryDiagnostics(s1RouteDisplayText)
                                                        suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                        npuStandardRouteS1DisplayText = s1RouteDisplayText
                                                        val s1Fallback = resolveNpuStandardRouteS1Fallback(
                                                            userPrompt = requestPrompt,
                                                            result = s1Result,
                                                        )
                                                        npuStandardRouteS1FallbackText = s1Fallback?.text
                                                        val npuFailureAssistantText = resolveNpuStandardRouteFailureAssistantMessage(
                                                            result = s1Result,
                                                            transientFallback = s1Fallback,
                                                        )
                                                        if (npuFailureAssistantText != null && !localStopRequested) {
                                                            npuStandardRouteS1FallbackText = null
                                                            withContext(Dispatchers.IO) {
                                                                viewModel.insertAssistantMessageAndReturnId(
                                                                    createAssistantMessage(
                                                                        chatId = currentChatId,
                                                                        response = npuFailureAssistantText,
                                                                        localSourceSummary = s1DisplayTextForDev,
                                                                    )
                                                                )
                                                            }
                                                        }
                                                        npuStandardRouteS1DevTraceText = if (
                                                            BuildConfig.DEBUG &&
                                                            developerAccessEnabled
                                                        ) {
                                                            buildNpuStandardRouteS1DevTraceText(
                                                                input = requestPrompt,
                                                                result = s1Result,
                                                                maxOutputTokens = npuStandardRouteMaxOutputTokens,
                                                                transientFallback = s1Fallback?.kind,
                                                                preferredBackendSetting = preferredBackendDryRunSetting,
                                                                npuStandardRouteMode = effectiveNpuStandardRouteMode,
                                                                npuStandardRouteSelectionSource = npuStandardRouteSelectionSource,
                                                            )
                                                        } else {
                                                            null
                                                        }
                                                        npuStandardRouteS1DevInputText = if (
                                                            BuildConfig.DEBUG &&
                                                            developerAccessEnabled
                                                        ) {
                                                            requestPrompt
                                                        } else {
                                                            null
                                                        }
                                                        npuStandardRouteS1DevOutputText = if (
                                                            BuildConfig.DEBUG &&
                                                            developerAccessEnabled
                                                        ) {
                                                            s1Result.actualDisplayText
                                                        } else {
                                                            null
                                                        }
                                                        npuStandardRouteS1DevCompactCopyText = if (
                                                            BuildConfig.DEBUG &&
                                                            developerAccessEnabled
                                                        ) {
                                                            buildNpuStandardRouteS1CompactExplicitCopyText(
                                                                input = requestPrompt,
                                                                result = s1Result,
                                                                maxOutputTokens = npuStandardRouteMaxOutputTokens,
                                                                transientFallback = s1Fallback?.kind,
                                                                appHistoryText = NpuStandardRouteS1AppHistory.formatForDev(context.applicationContext),
                                                                preferredBackendSetting = preferredBackendDryRunSetting,
                                                                npuStandardRouteMode = effectiveNpuStandardRouteMode,
                                                                npuStandardRouteSelectionSource = npuStandardRouteSelectionSource,
                                                            )
                                                        } else {
                                                            null
                                                        }
                                                        npuStandardRouteS1DevFullDumpCopyText = if (
                                                            BuildConfig.DEBUG &&
                                                            developerAccessEnabled
                                                        ) {
                                                            buildNpuStandardRouteS1FullDumpExplicitCopyText(
                                                                input = requestPrompt,
                                                                result = s1Result,
                                                                maxOutputTokens = npuStandardRouteMaxOutputTokens,
                                                                transientFallback = s1Fallback?.kind,
                                                                preferredBackendSetting = preferredBackendDryRunSetting,
                                                                npuStandardRouteMode = effectiveNpuStandardRouteMode,
                                                                npuStandardRouteSelectionSource = npuStandardRouteSelectionSource,
                                                            )
                                                        } else {
                                                            null
                                                        }
                                                        val npuFallbackBackendSetting =
                                                            resolveNpuStandardRouteLocalFallbackBackend(preferredBackendDryRunSetting)
                                                        if (
                                                            shouldFallbackNpuStandardRouteFailureToLocal(s1Result) &&
                                                            !localStopRequested
                                                        ) {
                                                            val fallbackResult = runLocalInferenceOnceEntry(
                                                                context = context.applicationContext,
                                                                settingsPreferences = settingsPreferences,
                                                                localBaseModelFilePath = localBaseModelFilePath,
                                                                localBaseModelDisplayName = localBaseModelDisplayName,
                                                                localGenericModelFilePath = localGenericModelFilePath,
                                                                localGenericModelDisplayName = localGenericModelDisplayName,
                                                                mediaPipeProbeContext = context.applicationContext,
                                                                preferredBackendDryRunSetting = npuFallbackBackendSetting,
                                                                markdownStreamingMode = markdownStreamingMode,
                                                                prompt = requestPrompt,
                                                                onPartial = { partial ->
                                                                    suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                                    localStreamingResponseText = partial
                                                                    streamingResponseTextForRender = partial
                                                                },
                                                            )
                                                            val fallbackResponse = fallbackResult.response?.trim().orEmpty()
                                                            val cpuFallbackResult = if (
                                                                fallbackResponse.isBlank() &&
                                                                npuFallbackBackendSetting == PreferredBackendDryRunSetting.GPU
                                                            ) {
                                                                runLocalInferenceOnceEntry(
                                                                    context = context.applicationContext,
                                                                    settingsPreferences = settingsPreferences,
                                                                    localBaseModelFilePath = localBaseModelFilePath,
                                                                    localBaseModelDisplayName = localBaseModelDisplayName,
                                                                    localGenericModelFilePath = localGenericModelFilePath,
                                                                    localGenericModelDisplayName = localGenericModelDisplayName,
                                                                    mediaPipeProbeContext = context.applicationContext,
                                                                    preferredBackendDryRunSetting = PreferredBackendDryRunSetting.CPU,
                                                                    markdownStreamingMode = markdownStreamingMode,
                                                                    prompt = requestPrompt,
                                                                    onPartial = { partial ->
                                                                        suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                                        localStreamingResponseText = partial
                                                                        streamingResponseTextForRender = partial
                                                                    },
                                                                )
                                                            } else {
                                                                null
                                                            }
                                                            val finalFallbackResult = cpuFallbackResult
                                                                ?.takeIf { !it.response?.trim().isNullOrBlank() }
                                                                ?: fallbackResult
                                                            val finalFallbackBackend =
                                                                if (finalFallbackResult === cpuFallbackResult) {
                                                                    PreferredBackendDryRunSetting.CPU
                                                                } else {
                                                                    npuFallbackBackendSetting
                                                                }
                                                            val finalFallbackResponse =
                                                                finalFallbackResult.response?.trim().orEmpty()
                                                            val fallbackLocalFailureReason = buildNpuStandardRouteFallbackLocalFailureReason(
                                                                localFailureDiagnosticsText = finalFallbackResult.trace.localFailureDiagnosticsText,
                                                            )
                                                            val fallbackDiagnostics = buildString {
                                                                appendLine("npu_standard_route_fallback_used=true")
                                                                appendLine("npu_standard_route_fallback_backend=${finalFallbackBackend.name}")
                                                                appendLine("npu_standard_route_fallback_reason=${s1Result.reason}")
                                                                appendLine("npu_standard_route_fallback_local_failure_reason=$fallbackLocalFailureReason")
                                                                appendLine("npu_standard_route_fallback_state=${finalFallbackResult.state}")
                                                                appendLine("npu_standard_route_fallback_response_length=${finalFallbackResponse.length}")
                                                                appendLine("npu_standard_route_gpu_fallback_state=${fallbackResult.state}")
                                                                appendLine("npu_standard_route_cpu_fallback_state=${cpuFallbackResult?.state ?: "not_attempted"}")
                                                                appendLine(s1DisplayTextForDev)
                                                                finalFallbackResult.trace.localFailureDiagnosticsText
                                                                    ?.takeIf { it.isNotBlank() }
                                                                    ?.let { appendLine(it) }
                                                            }.trimEnd()
                                                            suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                            npuStandardRouteS1DisplayText = s1RouteDisplayText
                                                            npuStandardRouteS1DevTraceText =
                                                                npuStandardRouteS1DevTraceText?.let { "$it\n$fallbackDiagnostics" }
                                                                    ?: fallbackDiagnostics
                                                            npuStandardRouteS1DevCompactCopyText =
                                                                npuStandardRouteS1DevCompactCopyText?.let { "$it\n$fallbackDiagnostics" }
                                                                    ?: fallbackDiagnostics
                                                            npuStandardRouteS1DevFullDumpCopyText =
                                                                npuStandardRouteS1DevFullDumpCopyText?.let { "$it\n$fallbackDiagnostics" }
                                                                    ?: fallbackDiagnostics
                                                            if (finalFallbackResponse.isNotBlank()) {
                                                                val fallbackAssistantResponsePrefix =
                                                                    if (s1Result.reason == NPU_STANDARD_ROUTE_MISSING_NATIVE_JNI_SYMBOL_REASON) {
                                                                        "このAPKではNPU実行に必要なnative部品が未搭載のため、GPU/CPUで応答します。"
                                                                    } else {
                                                                        "NPU推論に失敗したためGPU/CPUで応答します。"
                                                                    }
                                                                val fallbackAssistantResponse =
                                                                    "$fallbackAssistantResponsePrefix\n\n$finalFallbackResponse"
                                                                withContext(Dispatchers.IO) {
                                                                    viewModel.insertAssistantMessageAndReturnId(
                                                                        createAssistantMessage(
                                                                            chatId = currentChatId,
                                                                            response = fallbackAssistantResponse,
                                                                            localSourceSummary = fallbackDiagnostics,
                                                                        )
                                                                    )
                                                                }
                                                                localStreamingResponseText = null
                                                                streamingResponseTextForRender = null
                                                                showDelayedLocalRespondingPlaceholder = false
                                                                return@launch
                                                            } else {
                                                                val fallbackFailureMessage = buildNpuStandardRouteFallbackFailureMessage(
                                                                    localFailureDiagnosticsText = finalFallbackResult.trace.localFailureDiagnosticsText,
                                                                )
                                                                withContext(Dispatchers.IO) {
                                                                    viewModel.insertAssistantMessageAndReturnId(
                                                                        createAssistantMessage(
                                                                            chatId = currentChatId,
                                                                            response = fallbackFailureMessage,
                                                                            localSourceSummary = fallbackDiagnostics,
                                                                        )
                                                                    )
                                                                }
                                                                localStreamingResponseText = null
                                                                streamingResponseTextForRender = null
                                                                showDelayedLocalRespondingPlaceholder = false
                                                                return@launch
                                                            }
                                                        }
                                                        var npuStandardRouteUiAppendExecuted = false
                                                        var npuStandardRouteUiAppendVisibleCandidate = false
                                                        var npuStandardRouteUiAppendFailureReason = "none"
                                                        var npuStandardRouteTtsRequested = false
                                                        var npuStandardRouteTtsStarted = false
                                                        var npuStandardRouteDbSaveExecuted = false
                                                        var npuStandardRouteDbSavedTextLength = 0
                                                        var npuStandardRouteDbAssistantIdPresent = false
                                                        var npuStandardRouteDbMessageReplacedTransient = false
                                                        var npuStandardRouteDbConversationIdPresent = currentChatId > 0
                                                        var npuStandardRouteDbSaveBlockReason =
                                                            npuStandardRoutePhaseDiagnostics[
                                                                "npu_standard_route_db_save_block_reason"
                                                            ] ?: "none"
                                                        var npuStandardRouteMarkdownExecuted = false
                                                        var npuStandardRouteMarkdownMode = "none"
                                                        var npuStandardRouteMarkdownBlockReason =
                                                            npuStandardRoutePhaseDiagnostics[
                                                                "npu_standard_route_markdown_block_reason"
                                                            ] ?: "none"
                                                        var npuStandardRouteStreamingExecuted = false
                                                        var npuStandardRouteStreamingMode = "none"
                                                        var npuStandardRouteStreamingSource = "none"
                                                        var npuStandardRouteStreamingChunkCount = 0
                                                        var npuStandardRouteStreamingFinalTextLength = 0
                                                        var npuStandardRouteStreamingBlockReason =
                                                            npuStandardRoutePhaseDiagnostics[
                                                                "npu_standard_route_streaming_block_reason"
                                                            ] ?: "none"
                                                        val npuStandardRouteNativeStreamingUsed = false
                                                        var npuStandardRouteStreamingTextMatchesDb = false
                                                        var npuStandardRouteStreamingTextMatchesMarkdown = false
                                                        var npuStandardRouteDeliveryPath = when {
                                                            npuStandardRoutePhaseGateActive && npuStandardRouteDbSaveAllowed ->
                                                                "phase6_pending_db_save"
                                                            npuStandardRouteUiAppendAllowed -> "phase4_5_pending_delivery"
                                                            npuStandardRoutePhaseGateActive -> "phase_gate_suppressed"
                                                            else -> "standard_route_legacy"
                                                        }
                                                        var npuStandardRouteTtsExecutionBlockReason = "none"
                                                        val npuStandardRouteSafeUiText = s1Result.actualDisplayText
                                                            .ifBlank { s1Result.preparedOutput }
                                                            .ifBlank { s1Result.sanitizedOutput }
                                                            .trim()
                                                        var npuStandardRouteAssistantTextForPersist =
                                                            npuStandardRouteSafeUiText
                                                        if (
                                                            npuStandardRouteUiAppendAllowed &&
                                                            npuStandardRouteSafeUiText.isNotBlank() &&
                                                            !localStopRequested
                                                        ) {
                                                            npuStandardRoutePhaseUiAppendText = if (npuStandardRouteDbSaveAllowed) {
                                                                null
                                                            } else {
                                                                npuStandardRouteSafeUiText
                                                            }
                                                            showDelayedLocalRespondingPlaceholder = false
                                                            npuStandardRouteDeliveryPath = if (npuStandardRouteDbSaveAllowed) {
                                                                "phase6_db_save_pending"
                                                            } else if (npuStandardRouteTtsAllowed) {
                                                                "phase5_in_memory_ui_append"
                                                            } else {
                                                                "phase4_in_memory_ui_append"
                                                            }
                                                            if (!npuStandardRouteDbSaveAllowed) {
                                                                npuStandardRouteUiAppendExecuted = true
                                                                npuStandardRouteUiAppendVisibleCandidate = true
                                                            }
                                                        } else if (npuStandardRouteUiAppendAllowed) {
                                                            npuStandardRoutePhaseUiAppendText = null
                                                            npuStandardRouteUiAppendFailureReason = if (localStopRequested) {
                                                                "local_stop_requested"
                                                            } else {
                                                                "safe_text_empty"
                                                            }
                                                            npuStandardRouteDeliveryPath = "phase_ui_append_blocked_empty_or_stopped"
                                                        } else {
                                                            npuStandardRoutePhaseUiAppendText = null
                                                            npuStandardRouteUiAppendFailureReason =
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_ui_append_block_reason"
                                                                ] ?: "ui_append_not_allowed"
                                                        }
                                                        if (
                                                            npuStandardRoutePhaseGateActive &&
                                                            npuStandardRouteMarkdownAllowed &&
                                                            npuStandardRouteDbSaveAllowed &&
                                                            npuStandardRouteUiAppendAllowed &&
                                                            !localStopRequested
                                                        ) {
                                                            val markdownMapping = NpuStandardRouteS3MarkdownBridge()
                                                                .prepareMarkdownCandidate(
                                                                    s1Result = s1Result,
                                                                    finalizeMarkdown = { text ->
                                                                        buildFinalizedStreamingResponseForPersist(
                                                                            response = text,
                                                                            markdownStreamingMode = markdownStreamingMode,
                                                                        )
                                                                    },
                                                                )
                                                            val markdownCandidate = markdownMapping
                                                                .takeIf {
                                                                    shouldRenderNpuStandardRouteS3Markdown(
                                                                        enabled = true,
                                                                        mapping = it,
                                                                    )
                                                                }
                                                                ?.markdownCandidate
                                                            if (markdownCandidate != null) {
                                                                npuStandardRouteAssistantTextForPersist =
                                                                    markdownCandidate.finalizedText
                                                                npuStandardRouteMarkdownExecuted = true
                                                                npuStandardRouteMarkdownMode =
                                                                    markdownStreamingMode.name.lowercase()
                                                                npuStandardRouteMarkdownBlockReason = "none"
                                                                npuStandardRouteStreamingSource = "markdown_finalized_text"
                                                            } else {
                                                                npuStandardRouteMarkdownExecuted = false
                                                                npuStandardRouteMarkdownMode = "none"
                                                                npuStandardRouteMarkdownBlockReason =
                                                                    markdownMapping.failureReason
                                                                        ?: "markdown_candidate_unavailable"
                                                            }
                                                        } else if (
                                                            npuStandardRoutePhaseGateActive &&
                                                            npuStandardRouteMarkdownBlockReason == "none"
                                                        ) {
                                                            npuStandardRouteMarkdownBlockReason =
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_markdown_block_reason"
                                                                ] ?: "phase_not_markdown"
                                                        }
                                                        if (
                                                            npuStandardRoutePhaseGateActive &&
                                                            npuStandardRouteStreamingAllowed &&
                                                            npuStandardRouteMarkdownAllowed &&
                                                            npuStandardRouteMarkdownExecuted &&
                                                            npuStandardRouteDbSaveAllowed &&
                                                            npuStandardRouteUiAppendAllowed &&
                                                            !localStopRequested
                                                        ) {
                                                            val streamingFinalText = npuStandardRouteAssistantTextForPersist.trim()
                                                            val pseudoStreamingMapping = NpuStandardRouteS4PseudoStreamingBridge()
                                                                .preparePseudoStreamingCandidate(
                                                                    s1Result = s1Result,
                                                                    finalText = streamingFinalText,
                                                                    sourceDisplayText = s1DisplayTextForDev,
                                                                )
                                                            val pseudoStreamingCandidate = pseudoStreamingMapping
                                                                .takeIf {
                                                                    shouldStartNpuStandardRouteS4APseudoStreaming(
                                                                        enabled = true,
                                                                        mapping = it,
                                                                    )
                                                                }
                                                                ?.pseudoStreamingCandidate
                                                            if (pseudoStreamingCandidate != null) {
                                                                val s4GuardEpoch = streamingGuardEpoch
                                                                npuStandardRouteS4PseudoStreamingActive = true
                                                                npuStandardRouteStreamingSentenceTtsBlocked = true
                                                                try {
                                                                    pseudoStreamingCandidate.chunks.forEach { chunk ->
                                                                        if (
                                                                            !shouldContinueNpuStandardRouteS4APseudoStreaming(
                                                                                localStopRequested = localStopRequested,
                                                                                runGuardEpoch = s4GuardEpoch,
                                                                                currentGuardEpoch = streamingGuardEpoch,
                                                                                expectedChatId = currentChatId,
                                                                                currentChatId = effectiveChatId,
                                                                            )
                                                                        ) {
                                                                            return@launch
                                                                        }
                                                                        localStreamingResponseText = chunk
                                                                        streamingResponseTextForRender = chunk
                                                                        npuStandardRouteS4PseudoStreamingText = chunk
                                                                        delay(NPU_STANDARD_ROUTE_S4A_PSEUDO_STREAMING_CHUNK_DELAY_MS)
                                                                    }
                                                                    localStreamingResponseText = pseudoStreamingCandidate.finalText
                                                                    streamingResponseTextForRender = pseudoStreamingCandidate.finalText
                                                                    npuStandardRouteS4PseudoStreamingText = pseudoStreamingCandidate.finalText
                                                                    npuStandardRouteStreamingExecuted = true
                                                                    npuStandardRouteStreamingMode = "pseudo_final_text"
                                                                    npuStandardRouteStreamingSource =
                                                                        if (npuStandardRouteMarkdownExecuted) {
                                                                            "markdown_finalized_text"
                                                                        } else {
                                                                            "safe_final_text"
                                                                        }
                                                                    npuStandardRouteStreamingChunkCount =
                                                                        pseudoStreamingCandidate.chunks.size
                                                                    npuStandardRouteStreamingFinalTextLength =
                                                                        pseudoStreamingCandidate.finalText.length
                                                                    npuStandardRouteStreamingBlockReason = "none"
                                                                    npuStandardRouteStreamingTextMatchesDb =
                                                                        pseudoStreamingCandidate.finalText ==
                                                                            npuStandardRouteAssistantTextForPersist
                                                                    npuStandardRouteStreamingTextMatchesMarkdown =
                                                                        !npuStandardRouteMarkdownExecuted ||
                                                                            pseudoStreamingCandidate.finalText ==
                                                                            npuStandardRouteAssistantTextForPersist
                                                                    npuStandardRouteDeliveryPath =
                                                                        "phase8_pseudo_streaming_pending_db"
                                                                } finally {
                                                                    npuStandardRouteS4PseudoStreamingActive = false
                                                                    npuStandardRouteStreamingSentenceTtsBlocked = false
                                                                }
                                                            } else {
                                                                npuStandardRouteStreamingExecuted = false
                                                                npuStandardRouteStreamingMode = "none"
                                                                npuStandardRouteStreamingSource = "none"
                                                                npuStandardRouteStreamingBlockReason =
                                                                    pseudoStreamingMapping.failureReason
                                                                        ?: "pseudo_streaming_candidate_unavailable"
                                                            }
                                                        } else if (
                                                            npuStandardRoutePhaseGateActive &&
                                                            npuStandardRouteStreamingBlockReason == "none"
                                                        ) {
                                                            npuStandardRouteStreamingBlockReason = when {
                                                                npuStandardRouteStreamingAllowed && !npuStandardRouteMarkdownExecuted ->
                                                                    npuStandardRouteMarkdownBlockReason
                                                                else ->
                                                                    npuStandardRoutePhaseDiagnostics[
                                                                        "npu_standard_route_streaming_block_reason"
                                                                    ] ?: "phase_not_streaming"
                                                            }
                                                        }
                                                        if (
                                                            npuStandardRoutePhaseGateActive &&
                                                            npuStandardRouteDbSaveAllowed &&
                                                            npuStandardRouteUiAppendAllowed &&
                                                            !localStopRequested
                                                        ) {
                                                            if (npuStandardRouteAssistantTextForPersist.isBlank()) {
                                                                npuStandardRouteDbSaveBlockReason = "safe_text_empty"
                                                                npuStandardRouteDeliveryPath = "phase6_db_save_blocked_empty_text"
                                                            } else if (currentChatId <= 0) {
                                                                npuStandardRouteDbSaveBlockReason = "chat_id_missing"
                                                                npuStandardRouteDeliveryPath = "phase6_db_save_blocked_chat_id_missing"
                                                            } else {
                                                                try {
                                                                    val assistantId = withContext(Dispatchers.IO) {
                                                                        viewModel.insertAssistantMessageAndReturnId(
                                                                            createAssistantMessage(
                                                                                chatId = currentChatId,
                                                                                response = npuStandardRouteAssistantTextForPersist,
                                                                                localSourceSummary = s1DisplayTextForDev,
                                                                            )
                                                                        ).toInt()
                                                                    }
                                                                    lastPersistedStreamingAssistantText =
                                                                        npuStandardRouteAssistantTextForPersist
                                                                    localStreamingResponseText = null
                                                                    streamingResponseTextForRender = null
                                                                    npuStandardRoutePhaseUiAppendText = null
                                                                    npuStandardRouteUiAppendExecuted = true
                                                                    npuStandardRouteUiAppendVisibleCandidate = true
                                                                    npuStandardRouteDbSaveExecuted = true
                                                                    npuStandardRouteDbSavedTextLength =
                                                                        npuStandardRouteAssistantTextForPersist.length
                                                                    npuStandardRouteDbAssistantIdPresent = assistantId > 0
                                                                    npuStandardRouteDbMessageReplacedTransient = true
                                                                    npuStandardRouteDbSaveBlockReason = "none"
                                                                    npuStandardRouteDeliveryPath =
                                                                        if (npuStandardRouteStreamingExecuted) {
                                                                            "phase8_pseudo_streaming_db_backed_ui_append_db_markdown"
                                                                        } else if (npuStandardRouteMarkdownExecuted) {
                                                                            "phase7_db_backed_ui_append_db_markdown"
                                                                        } else {
                                                                            "phase6_db_backed_ui_append_db"
                                                                        }
                                                                } catch (exception: Exception) {
                                                                    Log.w(
                                                                        "ChatScreen",
                                                                        "NPU phase6 DB save failed after gated output",
                                                                        exception,
                                                                    )
                                                                    npuStandardRouteDbSaveBlockReason = "db_save_exception"
                                                                    npuStandardRouteUiAppendFailureReason = "db_save_exception"
                                                                    npuStandardRouteDeliveryPath = "phase6_db_save_exception"
                                                                }
                                                            }
                                                        } else if (npuStandardRoutePhaseGateActive && npuStandardRouteDbSaveBlockReason == "none") {
                                                            npuStandardRouteDbSaveBlockReason =
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_db_save_block_reason"
                                                                ] ?: "phase_not_db_save"
                                                        }
                                                        if (npuStandardRouteTtsAllowed && !localStopRequested) {
                                                            val npuStandardRouteSafeTtsText = s1Result.ttsText
                                                                .ifBlank { s1Result.actualDisplayText }
                                                                .ifBlank { s1Result.preparedOutput }
                                                                .trim()
                                                            val phase5TtsMapping = NpuStandardRouteS5TtsBridge()
                                                                .prepareTtsCandidate(
                                                                    s1Result = s1Result,
                                                                    finalAssistantText = npuStandardRouteSafeTtsText,
                                                                    ttsEnabled = ttsEnabled,
                                                                    streamingActive = false,
                                                                    sanitizeForTts = ::sanitizeTextForTts,
                                                                )
                                                            val phase5TtsCandidate = phase5TtsMapping.ttsCandidate
                                                            npuStandardRouteTtsExecutionBlockReason = when {
                                                                !ttsEnabled -> NPU_STANDARD_ROUTE_S5_TTS_SKIP_TTS_DISABLED
                                                                !phase5TtsMapping.hasTtsCandidate ->
                                                                    phase5TtsMapping.failureReason
                                                                        ?: NPU_STANDARD_ROUTE_S5_TTS_SKIP_CANDIDATE_NULL
                                                                ttsController.isInCooldown() -> NPU_STANDARD_ROUTE_S5_TTS_SKIP_COOLDOWN
                                                                else -> NPU_STANDARD_ROUTE_S5_TTS_SKIP_NONE
                                                            }
                                                            if (
                                                                npuStandardRouteTtsExecutionBlockReason ==
                                                                NPU_STANDARD_ROUTE_S5_TTS_SKIP_NONE &&
                                                                phase5TtsCandidate != null
                                                            ) {
                                                                npuStandardRouteTtsRequested = true
                                                                try {
                                                                    maybeReleaseHeldEngineForTtsPlayback()
                                                                    ttsController.speak(phase5TtsCandidate.speakText)
                                                                    npuStandardRouteTtsStarted = true
                                                                    npuStandardRouteDeliveryPath =
                                                                        if (npuStandardRouteDbSaveExecuted) {
                                                                            if (npuStandardRouteStreamingExecuted) {
                                                                                "phase8_pseudo_streaming_ui_append_tts_db_markdown"
                                                                            } else if (npuStandardRouteMarkdownExecuted) {
                                                                                "phase7_db_backed_ui_append_tts_db_markdown"
                                                                            } else {
                                                                                "phase6_db_backed_ui_append_tts_db"
                                                                            }
                                                                        } else {
                                                                            "phase5_in_memory_ui_append_and_tts"
                                                                        }
                                                                } catch (exception: Exception) {
                                                                    Log.w(
                                                                        "ChatScreen",
                                                                        "NPU phase5 direct TTS failed after gated output",
                                                                        exception,
                                                                    )
                                                                    npuStandardRouteTtsExecutionBlockReason =
                                                                        NpuStandardRouteS5TtsContract.REASON_TTS_EXCEPTION
                                                                    npuStandardRouteDeliveryPath =
                                                                        if (npuStandardRouteDbSaveExecuted) {
                                                                            if (npuStandardRouteStreamingExecuted) {
                                                                                "phase8_pseudo_streaming_ui_append_db_markdown_tts_exception"
                                                                            } else if (npuStandardRouteMarkdownExecuted) {
                                                                                "phase7_db_backed_ui_append_db_markdown_tts_exception"
                                                                            } else {
                                                                                "phase6_db_backed_ui_append_db_tts_exception"
                                                                            }
                                                                        } else {
                                                                            "phase5_in_memory_ui_append_tts_exception"
                                                                        }
                                                                }
                                                            }
                                                        } else if (npuStandardRoutePhaseGateActive) {
                                                            npuStandardRouteTtsExecutionBlockReason =
                                                                npuStandardRoutePhaseDiagnostics[
                                                                    "npu_standard_route_tts_block_reason"
                                                                ] ?: "phase_not_tts"
                                                        }
                                                        val npuStandardRouteExecutionDiagnosticsText =
                                                            buildNpuStandardRoutePhase1DiagnosticLines(
                                                                buildNpuStandardRouteDeliveryExecutionDiagnostics(
                                                                    uiAppendExecuted = npuStandardRouteUiAppendExecuted,
                                                                    uiAppendVisibleCandidate = npuStandardRouteUiAppendVisibleCandidate,
                                                                    ttsRequested = npuStandardRouteTtsRequested,
                                                                    ttsStarted = npuStandardRouteTtsStarted,
                                                                    deliveryPath = npuStandardRouteDeliveryPath,
                                                                    uiAppendTarget = if (npuStandardRouteUiAppendExecuted) {
                                                                        if (npuStandardRouteDbSaveExecuted) {
                                                                            "db_backed_assistant_message"
                                                                        } else {
                                                                            "transient_chat_message"
                                                                        }
                                                                    } else {
                                                                        "none"
                                                                    },
                                                                    uiAppendFailureReason = npuStandardRouteUiAppendFailureReason,
                                                                    ttsExecutionBlockReason = npuStandardRouteTtsExecutionBlockReason,
                                                                    dbSaveExecuted = npuStandardRouteDbSaveExecuted,
                                                                    dbSaveTarget = if (npuStandardRouteDbSaveExecuted) {
                                                                        "assistant_message"
                                                                    } else {
                                                                        "none"
                                                                    },
                                                                    dbSavedTextLength = npuStandardRouteDbSavedTextLength,
                                                                    dbAssistantIdPresent = npuStandardRouteDbAssistantIdPresent,
                                                                    dbSaveBlockReason = npuStandardRouteDbSaveBlockReason,
                                                                    dbMessageReplacedTransient = npuStandardRouteDbMessageReplacedTransient,
                                                                    dbConversationIdPresent = npuStandardRouteDbConversationIdPresent,
                                                                    markdownExecuted = npuStandardRouteMarkdownExecuted,
                                                                    markdownMode = npuStandardRouteMarkdownMode,
                                                                    markdownBlockReason = npuStandardRouteMarkdownBlockReason,
                                                                    streamingExecuted = npuStandardRouteStreamingExecuted,
                                                                    streamingMode = npuStandardRouteStreamingMode,
                                                                    streamingSource = npuStandardRouteStreamingSource,
                                                                    streamingChunkCount = npuStandardRouteStreamingChunkCount,
                                                                    streamingFinalTextLength = npuStandardRouteStreamingFinalTextLength,
                                                                    streamingBlockReason = npuStandardRouteStreamingBlockReason,
                                                                    nativeStreamingUsed = npuStandardRouteNativeStreamingUsed,
                                                                    streamingTextMatchesDb = npuStandardRouteStreamingTextMatchesDb,
                                                                    streamingTextMatchesMarkdown = npuStandardRouteStreamingTextMatchesMarkdown,
                                                                ),
                                                            ).joinToString("\n")
                                                        fun appendNpuStandardRouteExecutionDiagnostics(text: String?): String? =
                                                            if (text.isNullOrBlank()) {
                                                                text
                                                            } else {
                                                                "$text\n$npuStandardRouteExecutionDiagnosticsText"
                                                            }
                                                        suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                        npuStandardRouteS1DevTraceText =
                                                            appendNpuStandardRouteExecutionDiagnostics(npuStandardRouteS1DevTraceText)
                                                        npuStandardRouteS1DevCompactCopyText =
                                                            appendNpuStandardRouteExecutionDiagnostics(npuStandardRouteS1DevCompactCopyText)
                                                        npuStandardRouteS1DevFullDumpCopyText =
                                                            appendNpuStandardRouteExecutionDiagnostics(npuStandardRouteS1DevFullDumpCopyText)
                                                        npuStandardRouteS4PseudoStreamingText = null
                                                        npuStandardRouteS4PseudoStreamingActive = false
                                                        if (npuStandardRouteS2DbEnabled && npuStandardRouteLegacyDbSaveAllowed) {
                                                            val s2DbMapping = NpuStandardRouteS2DbBridge().prepareSaveCandidate(
                                                                userPrompt = requestPrompt,
                                                                s1Result = s1Result,
                                                            )
                                                            if (shouldPersistNpuStandardRouteS2Db(
                                                                    enabled = npuStandardRouteS2DbEnabled,
                                                                    mapping = s2DbMapping,
                                                                )
                                                            ) {
                                                                val saveCandidate = requireNotNull(s2DbMapping.saveCandidate)
                                                                val s2SavedResult = buildNpuStandardRouteS2DbSavedResult(s1Result)
                                                                val s3MarkdownMapping =
                                                                    if (npuStandardRouteS3MarkdownEnabled && npuStandardRouteMarkdownAllowed) {
                                                                        NpuStandardRouteS3MarkdownBridge().prepareMarkdownCandidate(
                                                                            s1Result = s1Result,
                                                                            finalizeMarkdown = { text ->
                                                                                buildFinalizedStreamingResponseForPersist(
                                                                                    response = text,
                                                                                    markdownStreamingMode = markdownStreamingMode,
                                                                                )
                                                                            },
                                                                        )
                                                                    } else {
                                                                        null
                                                                    }
                                                                val s3MarkdownCandidate = s3MarkdownMapping
                                                                    ?.takeIf {
                                                                        shouldRenderNpuStandardRouteS3Markdown(
                                                                            enabled = npuStandardRouteS3MarkdownEnabled,
                                                                            mapping = it,
                                                                        )
                                                                    }
                                                                    ?.markdownCandidate
                                                                val assistantTextForPersist =
                                                                    s3MarkdownCandidate?.finalizedText
                                                                        ?: saveCandidate.assistantMessage.text
                                                                val npuStandardRouteMarkdownResult =
                                                                    if (s3MarkdownCandidate != null) {
                                                                        buildNpuStandardRouteS3MarkdownSavedResult(
                                                                            s1Result = s1Result,
                                                                            finalizedText = s3MarkdownCandidate.finalizedText,
                                                                        )
                                                                    } else {
                                                                        s2SavedResult
                                                                    }
                                                                val s4PseudoStreamingCandidate =
                                                                    if (
                                                                        npuStandardRouteS4aPseudoStreamingEnabled &&
                                                                        npuStandardRouteStreamingAllowed &&
                                                                        s3MarkdownCandidate != null
                                                                    ) {
                                                                        val s4PseudoStreamingMapping = NpuStandardRouteS4PseudoStreamingBridge()
                                                                            .preparePseudoStreamingCandidate(
                                                                                s1Result = s1Result,
                                                                                finalText = s3MarkdownCandidate.finalizedText,
                                                                                sourceDisplayText = npuStandardRouteMarkdownResult.displayText,
                                                                            )
                                                                        s4PseudoStreamingMapping
                                                                            .takeIf {
                                                                                shouldStartNpuStandardRouteS4APseudoStreaming(
                                                                                    enabled = npuStandardRouteS4aPseudoStreamingEnabled,
                                                                                    mapping = it,
                                                                                )
                                                                            }
                                                                            ?.pseudoStreamingCandidate
                                                                    } else {
                                                                        null
                                                                    }
                                                                val npuStandardRoutePersistedResult =
                                                                    if (s4PseudoStreamingCandidate != null) {
                                                                        buildNpuStandardRouteS4APseudoStreamingSavedResult(
                                                                            s1Result = s1Result,
                                                                            finalText = s4PseudoStreamingCandidate.finalText,
                                                                        )
                                                                    } else {
                                                                        npuStandardRouteMarkdownResult
                                                                    }
                                                                val npuStandardRoutePersistedDisplayTextWithMemory =
                                                                    appendNpuS1MemoryDiagnostics(
                                                                        npuStandardRoutePersistedResult.displayText,
                                                                    )
                                                                suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                                npuStandardRouteS1DisplayText = npuStandardRoutePersistedResult.displayText
                                                                if (s4PseudoStreamingCandidate != null) {
                                                                    val s4GuardEpoch = streamingGuardEpoch
                                                                    npuStandardRouteS4PseudoStreamingActive = true
                                                                    npuStandardRouteStreamingSentenceTtsBlocked = true
                                                                    try {
                                                                        s4PseudoStreamingCandidate.chunks.forEach { chunk ->
                                                                            if (
                                                                                !shouldContinueNpuStandardRouteS4APseudoStreaming(
                                                                                    localStopRequested = localStopRequested,
                                                                                    runGuardEpoch = s4GuardEpoch,
                                                                                    currentGuardEpoch = streamingGuardEpoch,
                                                                                    expectedChatId = currentChatId,
                                                                                    currentChatId = effectiveChatId,
                                                                                )
                                                                            ) {
                                                                                return@launch
                                                                            }
                                                                            localStreamingResponseText = chunk
                                                                            streamingResponseTextForRender = chunk
                                                                            npuStandardRouteS4PseudoStreamingText = chunk
                                                                            delay(NPU_STANDARD_ROUTE_S4A_PSEUDO_STREAMING_CHUNK_DELAY_MS)
                                                                        }
                                                                        localStreamingResponseText = s4PseudoStreamingCandidate.finalText
                                                                        streamingResponseTextForRender = s4PseudoStreamingCandidate.finalText
                                                                        npuStandardRouteS4PseudoStreamingText = s4PseudoStreamingCandidate.finalText
                                                                    } finally {
                                                                        npuStandardRouteS4PseudoStreamingActive = false
                                                                    }
                                                                    if (
                                                                        !shouldContinueNpuStandardRouteS4APseudoStreaming(
                                                                            localStopRequested = localStopRequested,
                                                                            runGuardEpoch = s4GuardEpoch,
                                                                            currentGuardEpoch = streamingGuardEpoch,
                                                                            expectedChatId = currentChatId,
                                                                            currentChatId = effectiveChatId,
                                                                        )
                                                                    ) {
                                                                        return@launch
                                                                    }
                                                                }
                                                                val resolvedChatId = currentChatId
                                                                val npuStandardRouteInferenceStats =
                                                                    buildNpuStandardRouteInferenceStats(
                                                                        result = npuStandardRoutePersistedResult,
                                                                        localSourceSummary = npuStandardRoutePersistedDisplayTextWithMemory,
                                                                        assistantText = assistantTextForPersist,
                                                                    )
                                                                val assistantId = withContext(Dispatchers.IO) {
                                                                    viewModel.insertAssistantMessageAndReturnId(
                                                                        createAssistantMessage(
                                                                            chatId = resolvedChatId,
                                                                            response = assistantTextForPersist,
                                                                            latestInferenceStats = npuStandardRouteInferenceStats,
                                                                            localSourceSummary = npuStandardRoutePersistedDisplayTextWithMemory,
                                                                        )
                                                                    ).toInt()
                                                                }
                                                                lastPersistedStreamingAssistantText = assistantTextForPersist
                                                                localStreamingResponseText = null
                                                                streamingResponseTextForRender = null
                                                                npuStandardRouteStreamingSentenceTtsBlocked = false
                                                                if (npuStandardRouteS5TtsEnabled && npuStandardRouteLegacyS5TtsAllowed) {
                                                                    val s5TtsMapping = NpuStandardRouteS5TtsBridge()
                                                                        .prepareTtsCandidate(
                                                                            s1Result = s1Result,
                                                                            finalAssistantText = s1Result.ttsText,
                                                                            ttsEnabled = ttsEnabled,
                                                                            streamingActive = npuStandardRouteS4PseudoStreamingActive,
                                                                            sanitizeForTts = ::sanitizeTextForTts,
                                                                        )
                                                                    logStreamTrace(
                                                                        buildNpuStandardRouteS5TtsCandidateTrace(
                                                                            mapping = s5TtsMapping,
                                                                            finalTextLength = s1Result.ttsText.length,
                                                                            ttsEnabled = ttsEnabled,
                                                                            streamingActive = npuStandardRouteS4PseudoStreamingActive,
                                                                            assistantId = assistantId,
                                                                        ),
                                                                    )
                                                                    val s5TtsSkipReason = classifyNpuStandardRouteS5TtsSkipReason(
                                                                        enabled = npuStandardRouteS5TtsEnabled && npuStandardRouteLegacyS5TtsAllowed,
                                                                        mapping = s5TtsMapping,
                                                                        ttsEnabled = ttsEnabled,
                                                                        streamingActive = npuStandardRouteS4PseudoStreamingActive,
                                                                        assistantId = assistantId,
                                                                        suppressedForAssistant = isTtsSuppressedForAssistant(assistantId),
                                                                        inCooldown = ttsController.isInCooldown(),
                                                                    )
                                                                    if (s5TtsSkipReason == NPU_STANDARD_ROUTE_S5_TTS_SKIP_NONE) {
                                                                        val ttsCandidate = requireNotNull(s5TtsMapping.ttsCandidate)
                                                                        currentSpeakingAssistantMessageId = assistantId
                                                                        stopButtonOwnerAssistantMessageId = assistantId
                                                                        stopButtonOwnerSetAtMs = SystemClock.elapsedRealtime()
                                                                        maybeReleaseHeldEngineForTtsPlayback()
                                                                        logStreamTrace(
                                                                            buildNpuStandardRouteS5TtsSpeakTrace(
                                                                                stage = "before",
                                                                                assistantId = assistantId,
                                                                                speakTextLength = ttsCandidate.speakText.length,
                                                                            ),
                                                                        )
                                                                            val s5SavedResult = try {
                                                                                ttsController.speak(ttsCandidate.speakText)
                                                                                buildNpuStandardRouteS5TtsSavedResult(
                                                                                    s1Result = s1Result,
                                                                                    finalAssistantText = s1Result.ttsText,
                                                                                    ttsDiagnostics = NpuStandardRouteS5TtsContract.successDiagnostics(
                                                                                        s1Result.ttsText,
                                                                                    ),
                                                                                )
                                                                            } catch (exception: Exception) {
                                                                                Log.w("ChatScreen", "NPU S5 TTS failed after successful inference", exception)
                                                                                if (currentSpeakingAssistantMessageId == assistantId) {
                                                                                    currentSpeakingAssistantMessageId = null
                                                                                }
                                                                                if (stopButtonOwnerAssistantMessageId == assistantId) {
                                                                                    stopButtonOwnerAssistantMessageId = null
                                                                                    stopButtonOwnerSetAtMs = null
                                                                                }
                                                                                buildNpuStandardRouteS5TtsSavedResult(
                                                                                    s1Result = s1Result,
                                                                                    finalAssistantText = s1Result.ttsText,
                                                                                    ttsDiagnostics = NpuStandardRouteS5TtsContract.exceptionDiagnostics(
                                                                                        sanitizedOutput = s1Result.ttsText,
                                                                                        throwable = exception,
                                                                                    ),
                                                                                )
                                                                            }
                                                                            val s5SavedDisplayTextWithMemory =
                                                                                appendNpuS1MemoryDiagnostics(s5SavedResult.displayText)
                                                                            suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                                            npuStandardRouteS1DisplayText = s5SavedDisplayTextWithMemory
                                                                            try {
                                                                                withContext(Dispatchers.IO) {
                                                                                    viewModel.getMessageById(assistantId)?.let { message ->
                                                                                        viewModel.updateMessage(
                                                                                            message.copy(localSourceSummary = s5SavedDisplayTextWithMemory),
                                                                                        )
                                                                                    }
                                                                                }
                                                                            } catch (exception: Exception) {
                                                                                Log.w("ChatScreen", "Failed to update NPU S5 TTS diagnostics", exception)
                                                                            }
                                                                            logStreamTrace(
                                                                                buildNpuStandardRouteS5TtsSpeakTrace(
                                                                                    stage = if (s5SavedResult.s5TtsDiagnostics?.completed == true) {
                                                                                        "after"
                                                                                    } else {
                                                                                        NpuStandardRouteS5TtsContract.REASON_TTS_EXCEPTION
                                                                                    },
                                                                                    assistantId = assistantId,
                                                                                    speakTextLength = ttsCandidate.speakText.length,
                                                                                ),
                                                                            )
                                                                        } else {
                                                                            logStreamTrace(
                                                                                buildNpuStandardRouteS5TtsSkipTrace(
                                                                                    reason = s5TtsSkipReason,
                                                                                    assistantId = assistantId,
                                                                                ),
                                                                            )
                                                                        }
                                                                    } else {
                                                                        logStreamTrace(
                                                                            buildNpuStandardRouteS5TtsSkipTrace(
                                                                                reason = NPU_STANDARD_ROUTE_S5_TTS_SKIP_GATE_OFF,
                                                                                assistantId = assistantId,
                                                                            ),
                                                                        )
                                                                    }
                                                                return@launch
                                                            } else {
                                                                suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                                npuStandardRouteS1DisplayText = appendNpuS1MemoryDiagnostics(
                                                                    buildNpuStandardRouteS2DbSkippedResult(
                                                                        s1Result = s1Result,
                                                                        failureReason = s2DbMapping.failureReason,
                                                                    ).displayText,
                                                                )
                                                            }
                                                        }
                                                                val s4DisplayOnlyCandidate =
                                                            if (npuStandardRouteS4aPseudoStreamingEnabled && npuStandardRouteStreamingAllowed) {
                                                                val s4DisplayOnlyMapping = NpuStandardRouteS4PseudoStreamingBridge()
                                                                    .preparePseudoStreamingCandidate(
                                                                        s1Result = s1Result,
                                                                        finalText = s1Result.actualDisplayText,
                                                                        sourceDisplayText = s1Result.displayText,
                                                                    )
                                                                s4DisplayOnlyMapping
                                                                    .takeIf {
                                                                        shouldStartNpuStandardRouteS4APseudoStreaming(
                                                                            enabled = npuStandardRouteS4aPseudoStreamingEnabled,
                                                                            mapping = it,
                                                                        )
                                                                    }
                                                                    ?.pseudoStreamingCandidate
                                                            } else {
                                                                null
                                                        }
                                                        if (!npuStandardRouteS5TtsEnabled || !npuStandardRouteLegacyS5TtsAllowed) {
                                                            logStreamTrace(
                                                                buildNpuStandardRouteS5TtsSkipTrace(
                                                                    reason = NPU_STANDARD_ROUTE_S5_TTS_SKIP_GATE_OFF,
                                                                    assistantId = null,
                                                                ),
                                                            )
                                                        }
                                                        if (
                                                            s4DisplayOnlyCandidate != null ||
                                                            (npuStandardRouteS5TtsEnabled && npuStandardRouteLegacyS5TtsAllowed)
                                                        ) {
                                                            coroutineScope.launch {
                                                                if (s4DisplayOnlyCandidate != null) {
                                                                    npuStandardRouteS4PseudoStreamingActive = true
                                                                    s4DisplayOnlyCandidate.chunks.forEach { chunk ->
                                                                        npuStandardRouteS4PseudoStreamingText = chunk
                                                                        delay(NPU_STANDARD_ROUTE_S4A_PSEUDO_STREAMING_CHUNK_DELAY_MS)
                                                                    }
                                                                    suppressNpuStandardRouteDevDiagnosticsUntilReplyDisplayed = false
                                                                    npuStandardRouteS4PseudoStreamingText = s4DisplayOnlyCandidate.finalText
                                                                    npuStandardRouteS4PseudoStreamingActive = false
                                                                }
                                                                if (npuStandardRouteS5TtsEnabled && npuStandardRouteLegacyS5TtsAllowed) {
                                                                    val s5TtsMapping = NpuStandardRouteS5TtsBridge()
                                                                        .prepareTtsCandidate(
                                                                            s1Result = s1Result,
                                                                            finalAssistantText = s1Result.ttsText,
                                                                            ttsEnabled = ttsEnabled,
                                                                            streamingActive = npuStandardRouteS4PseudoStreamingActive,
                                                                            sanitizeForTts = ::sanitizeTextForTts,
                                                                        )
                                                                    logStreamTrace(
                                                                        buildNpuStandardRouteS5TtsCandidateTrace(
                                                                            mapping = s5TtsMapping,
                                                                            finalTextLength = s1Result.ttsText.length,
                                                                            ttsEnabled = ttsEnabled,
                                                                            streamingActive = npuStandardRouteS4PseudoStreamingActive,
                                                                            assistantId = null,
                                                                        ),
                                                                    )
                                                                    logStreamTrace(
                                                                        buildNpuStandardRouteS5TtsSkipTrace(
                                                                            reason = classifyNpuStandardRouteS5TtsSkipReason(
                                                                                enabled = npuStandardRouteS5TtsEnabled && npuStandardRouteLegacyS5TtsAllowed,
                                                                                mapping = s5TtsMapping,
                                                                                ttsEnabled = ttsEnabled,
                                                                                streamingActive = npuStandardRouteS4PseudoStreamingActive,
                                                                                assistantId = null,
                                                                                suppressedForAssistant = false,
                                                                                inCooldown = ttsController.isInCooldown(),
                                                                            ),
                                                                            assistantId = null,
                                                                        ),
                                                                    )
                                                                } else {
                                                                    logStreamTrace(
                                                                        buildNpuStandardRouteS5TtsSkipTrace(
                                                                            reason = NPU_STANDARD_ROUTE_S5_TTS_SKIP_GATE_OFF,
                                                                            assistantId = null,
                                                                        ),
                                                                    )
                                                                }
                                                            }
                                                        }
                                                            } catch (exception: CancellationException) {
                                                                if (!localStopRequested) throw exception
                                                            } catch (exception: Exception) {
                                                                Log.e("ChatScreen", "NPU standard route execution failed", exception)
                                                                NpuStandardRouteS1AppHistory.recordException(
                                                                    context = context.applicationContext,
                                                                    prompt = requestPrompt,
                                                                    throwable = exception,
                                                                )
                                                                val failureChatId = resolvedNpuChatId
                                                                if (!localStopRequested && failureChatId != null) {
                                                                    withContext(Dispatchers.IO) {
                                                                        viewModel.insertAssistantMessageAndReturnId(
                                                                            createAssistantMessage(
                                                                                chatId = failureChatId,
                                                                                response = "NPU推論の応答取得に失敗しました: ${exception.javaClass.simpleName}",
                                                                                localSourceSummary = exception.message.orEmpty(),
                                                                            )
                                                                        )
                                                                    }
                                                                }
                                                                snackbarHostState.currentSnackbarData?.dismiss()
                                                                snackbarHostState.showSnackbar(
                                                                    message = "NPU推論の応答取得に失敗しました",
                                                                    duration = SnackbarDuration.Short,
                                                                )
                                                            } finally {
                                                                npuStandardRouteS4PseudoStreamingActive = false
                                                                npuStandardRouteStreamingSentenceTtsBlocked = false
                                                                showDelayedLocalRespondingPlaceholder = false
                                                                isLocalInferenceRunning = false
                                                                localInferenceJob = null
                                                            }
                                                        }
                                                        return@localSendLaunch
                                                    }
                                                    val legacyQairt244ChatScreenRouteEnabled =
                                                        shouldEnterLegacyQairt244ChatScreenRoute(
                                                            hardGateEnabled = ENABLE_LEGACY_QAIRT244_CHATSCREEN_ROUTE,
                                                            debugBuild = BuildConfig.DEBUG,
                                                            customBuildExperiment = BuildConfig.CUSTOM_BUILD_EXPERIMENT,
                                                            developerAccessEnabled = developerAccessEnabled,
                                                            legacyToggleEnabled = devEnableQairt244Sm8750NpuRoute,
                                                        )
                                                    if (legacyQairt244ChatScreenRouteEnabled) {
                                                        // DEV-only experiment: when the toggle is OFF, execution falls through to the unchanged local route.
                                                        isLocalInferenceRunning = true
                                                        debugLocalUiTrace(
                                                            label = "DEV_QAIRT244_SM8750_NPU_SEND_TAPPED",
                                                            extra = "effectiveChatId=$effectiveChatId promptLength=${requestPrompt.length}",
                                                        )
                                                        prompt = ""
                                                        userPrompt = ""
                                                        selectedImageUriStrings = emptyList()
                                                        showDelayedLocalRespondingPlaceholder = false
                                                        localInferenceEngineState = LocalInferenceEngineState.READY
                                                        localStopRequested = false
                                                        stopTtsWithCleanup(
                                                            suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                                ?: currentSpeakingAssistantMessageId
                                                                ?: streamingSpeechStartedForMessageId,
                                                            armTapGuards = false,
                                                        )
                                                        localInferenceJob = coroutineScope.launch {
                                                            var currentChatId = effectiveChatId
                                                            if (currentChatId == null) {
                                                                isCreatingChat = true
                                                                try {
                                                                    val newChatId = withContext(Dispatchers.IO) {
                                                                        viewModel.insertChatAndReturnId(
                                                                            Chat(title = "New chat", titleSource = TitleSource.TEMP)
                                                                        )
                                                                    }
                                                                    effectiveChatId = newChatId
                                                                    pendingNavigateChatId = newChatId
                                                                    currentChatId = newChatId
                                                                } finally {
                                                                    isCreatingChat = false
                                                                }
                                                            }
                                                            val resolvedChatId = currentChatId
                                                            withContext(Dispatchers.IO) {
                                                                viewModel.insert(
                                                                    Message(
                                                                        chatId = resolvedChatId,
                                                                        message = requestPrompt,
                                                                        isSendbyMe = true,
                                                                    )
                                                                )
                                                            }
                                                            isLocalInferenceRunning = true
                                                            localStreamingResponseText = null
                                                            showDelayedLocalRespondingPlaceholder = false
                                                            try {
                                                                val devMemorySnapshots = mutableListOf(
                                                                    captureLocalMemorySnapshot(
                                                                        context = context.applicationContext,
                                                                        stage = MEMORY_STAGE_BEFORE_GENERATE,
                                                                    ),
                                                                    captureLocalMemorySnapshot(
                                                                        context = context.applicationContext,
                                                                        stage = MEMORY_STAGE_AFTER_PROMPT_BUILD,
                                                                    ),
                                                                    captureLocalMemorySnapshot(
                                                                        context = context.applicationContext,
                                                                        stage = MEMORY_STAGE_BEFORE_ENGINE_CALL,
                                                                    ),
                                                                )
                                                                val devResult = withContext(Dispatchers.IO) {
                                                                    runDevQairt244Sm8750NpuChatScreenRouteViaReflection(
                                                                        context = context.applicationContext,
                                                                        prompt = requestPrompt,
                                                                    )
                                                                }
                                                                val safetyGuardBlock = safetyGuardConversationBlockOrNull(
                                                                    chatId = resolvedChatId,
                                                                    reasonCode = devResult.reasonCode,
                                                                    failureStage = devResult.failureStage,
                                                                    stopReason = devResult.stopReason,
                                                                )
                                                                if (safetyGuardBlock != null) {
                                                                    safetyGuardBlockedConversations[resolvedChatId] = safetyGuardBlock
                                                                    devMemorySnapshots += captureLocalMemorySnapshot(
                                                                        context = context.applicationContext,
                                                                        stage = MEMORY_STAGE_SAFETY_GUARD_TRIGGERED,
                                                                    )
                                                                    devMemorySnapshots += captureLocalMemorySnapshot(
                                                                        context = context.applicationContext,
                                                                        stage = MEMORY_STAGE_AFTER_CANCEL,
                                                                    )
                                                                    npuStandardRouteS4PseudoStreamingActive = false
                                                                    npuStandardRouteStreamingSentenceTtsBlocked = true
                                                                    stopTtsWithCleanup(
                                                                        suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                                            ?: currentSpeakingAssistantMessageId
                                                                            ?: streamingSpeechStartedForMessageId,
                                                                        armTapGuards = false,
                                                                    )
                                                                    withContext(Dispatchers.IO) {
                                                                        localInferenceEngineHolder.resetConversation(
                                                                            chatId = resolvedChatId,
                                                                            reason = MEMORY_STAGE_SAFETY_GUARD_TRIGGERED,
                                                                            appendTrace = { message ->
                                                                                appendLocalReflectionTrace(
                                                                                    context = context.applicationContext,
                                                                                    message = message,
                                                                                )
                                                                            },
                                                                        )
                                                                        localInferenceEngineHolder.requestRecreateForDev(
                                                                            reason = MEMORY_STAGE_SAFETY_GUARD_TRIGGERED,
                                                                            appendTrace = { message ->
                                                                                appendLocalReflectionTrace(
                                                                                    context = context.applicationContext,
                                                                                    message = message,
                                                                                )
                                                                            },
                                                                        )
                                                                    }
                                                                    devMemorySnapshots += captureLocalMemorySnapshot(
                                                                        context = context.applicationContext,
                                                                        stage = MEMORY_STAGE_AFTER_ENGINE_RECYCLE,
                                                                    )
                                                                }
                                                                devMemorySnapshots += captureLocalMemorySnapshot(
                                                                    context = context.applicationContext,
                                                                    stage = if (devResult.success) {
                                                                        MEMORY_STAGE_GENERATION_FINISHED
                                                                    } else {
                                                                        MEMORY_STAGE_GENERATION_FAILED
                                                                    },
                                                                )
                                                                devMemorySnapshots += captureLocalMemorySnapshot(
                                                                    context = context.applicationContext,
                                                                    stage = MEMORY_STAGE_AFTER_RUNNER_DISPOSE,
                                                                )
                                                                val assistantText = if (safetyGuardBlock != null) {
                                                                    SAFETY_GUARD_BLOCKED_USER_MESSAGE
                                                                } else {
                                                                    devResult.assistantMessage.ifBlank {
                                                                        if (devResult.success) {
                                                                            devResult.output
                                                                        } else {
                                                                            "実験的NPU route failed: ${devResult.reasonCode}"
                                                                        }
                                                                    }
                                                                }
                                                                val memoryDiagnostics = formatMemoryDiagnosticsForDev(
                                                                    snapshots = devMemorySnapshots,
                                                                    guardBlock = safetyGuardBlock,
                                                                )
                                                                val sourceSummary = listOf(
                                                                    devResult.toLocalSourceSummary(),
                                                                    memoryDiagnostics,
                                                                ).filter { it.isNotBlank() }.joinToString("\n\n")
                                                                val stats = devResult.toInferenceStats().copy(
                                                                    finishReason = if (safetyGuardBlock != null) {
                                                                        MEMORY_STAGE_SAFETY_GUARD_TRIGGERED
                                                                    } else {
                                                                        devResult.toInferenceStats().finishReason
                                                                    },
                                                                    localSourceSummary = sourceSummary,
                                                                )
                                                                devDebugText = sourceSummary
                                                                if (!localStopRequested) {
                                                                    val assistantId = withContext(Dispatchers.IO) {
                                                                        viewModel.insertAssistantMessageAndReturnId(
                                                                            createAssistantMessage(
                                                                                chatId = resolvedChatId,
                                                                                response = assistantText,
                                                                                latestInferenceStats = stats,
                                                                                localSourceSummary = sourceSummary,
                                                                                generationTimeMs = devResult.elapsedMs,
                                                                            )
                                                                        ).toInt()
                                                                    }
                                                                    if (assistantId > 0) {
                                                                        immediateInferenceStatsByMessageId[assistantId] = stats
                                                                    }
                                                                    writeDevQairt244Sm8750DisplayDiagnostics(
                                                                        context = context.applicationContext,
                                                                        result = devResult,
                                                                        displayedAssistantText = assistantText,
                                                                        assistantMessageId = assistantId,
                                                                    )
                                                                }
                                                                cleanupDevQairt244NpuUiState(reason = if (safetyGuardBlock != null) {
                                                                    MEMORY_STAGE_SAFETY_GUARD_TRIGGERED
                                                                } else {
                                                                    "dev-qairt244-finish"
                                                                })
                                                                snackbarHostState.currentSnackbarData?.dismiss()
                                                                snackbarHostState.showSnackbar(
                                                                    message = if (safetyGuardBlock != null) {
                                                                        SAFETY_GUARD_BLOCKED_USER_MESSAGE
                                                                    } else if (devResult.success) {
                                                                        "実験的NPU route success"
                                                                    } else {
                                                                        "実験的NPU route failed: ${devResult.reasonCode}"
                                                                    },
                                                                    duration = SnackbarDuration.Short,
                                                                )
                                                            } catch (exception: Exception) {
                                                                devDebugText = listOf(
                                                                    "selected_route=qairt244_sm8750_hidden_npu",
                                                                    "failure_stage=ui_exception",
                                                                    "stop_reason=${exception.javaClass.simpleName}",
                                                                    "required_sm8750_model_path=false",
                                                                    "fallback_used=false",
                                                                    "normal_ui_route_connected=false",
                                                                    "message=${exception.message.orEmpty()}",
                                                                ).joinToString("\n")
                                                                if (!localStopRequested) {
                                                                    withContext(Dispatchers.IO) {
                                                                        viewModel.insertAssistantMessageAndReturnId(
                                                                            createAssistantMessage(
                                                                                chatId = resolvedChatId,
                                                                                response = "実験的NPU route failed: ${exception.javaClass.simpleName}",
                                                                                localSourceSummary = devDebugText,
                                                                            )
                                                                        )
                                                                    }
                                                                }
                                                                cleanupDevQairt244NpuUiState(reason = "dev-qairt244-exception")
                                                                snackbarHostState.currentSnackbarData?.dismiss()
                                                                snackbarHostState.showSnackbar(
                                                                    message = "実験的NPU route failed: ${exception.javaClass.simpleName}",
                                                                    duration = SnackbarDuration.Short,
                                                                )
                                                            } finally {
                                                                cleanupDevQairt244NpuUiState(reason = "dev-qairt244-finally")
                                                            }
                                                        }
                                                        return@localSendLaunch
                                                    }
                                                    debugLocalUiTrace(
                                                        label = "LOCAL_UI_SEND_TAPPED",
                                                        extra = "selectedInferenceTarget=$selectedInferenceTarget effectiveChatId=$effectiveChatId userPromptLength=${userPrompt.length}",
                                                    )
                                                    prompt = ""
                                                    userPrompt = ""
                                                    selectedImageUriStrings = emptyList()
                                                    showDelayedLocalRespondingPlaceholder = false
                                                    localInferenceEngineState = LocalInferenceEngineState.READY
                                                    localStopRequested = false
                                                    debugLocalUiTrace(
                                                        label = "LOCAL_UI_INPUT_CLEARED",
                                                        extra = "effectiveChatId=$effectiveChatId pendingNavigateChatId=$pendingNavigateChatId userPromptLengthAfterClear=${userPrompt.length}",
                                                    )
                                                    stopTtsWithCleanup(
                                                        suppressedMessageId = stopButtonOwnerAssistantMessageId
                                                            ?: currentSpeakingAssistantMessageId
                                                            ?: streamingSpeechStartedForMessageId,
                                                        armTapGuards = false,
                                                    )
                                                    localInferenceJob = coroutineScope.launch {
                                                        debugLocalUiTrace(
                                                            label = "LOCAL_UI_LAUNCH_ENTER",
                                                            extra = "effectiveChatId=$effectiveChatId pendingNavigateChatId=$pendingNavigateChatId isCreatingChat=$isCreatingChat",
                                                        )
                                                        var currentChatId = effectiveChatId
                                                        var localUserMessageAlreadyInserted = false
                                                        if (currentChatId == null) {
                                                            isCreatingChat = true
                                                            try {
                                                                val newChatId = withContext(Dispatchers.IO) {
                                                                    viewModel.insertChatAndReturnId(
                                                                        Chat(title = "New chat", titleSource = TitleSource.TEMP)
                                                                    )
                                                                }
                                                                effectiveChatId = newChatId
                                                                pendingNavigateChatId = newChatId
                                                                currentChatId = newChatId
                                                            } finally {
                                                                isCreatingChat = false
                                                            }
                                                        } else {
                                                            immediateLocalUserInsertJob?.join()
                                                            localUserMessageAlreadyInserted = true
                                                        }
                                                        val resolvedChatId = currentChatId
                                                        debugLocalUiTrace(
                                                            label = "LOCAL_UI_USER_INSERT_START",
                                                            extra = "resolvedChatId=$resolvedChatId requestPromptLength=${requestPrompt.length} alreadyInserted=$localUserMessageAlreadyInserted",
                                                        )
                                                        if (!localUserMessageAlreadyInserted) {
                                                            withContext(Dispatchers.IO) {
                                                                viewModel.insert(
                                                                    Message(
                                                                        chatId = resolvedChatId,
                                                                        message = requestPrompt,
                                                                        isSendbyMe = true,
                                                                    )
                                                                )
                                                            }
                                                        }
                                                        debugLocalUiTrace(
                                                            label = "LOCAL_UI_USER_INSERT_DONE",
                                                            extra = "resolvedChatId=$resolvedChatId requestPromptLength=${requestPrompt.length} alreadyInserted=$localUserMessageAlreadyInserted",
                                                        )
                                                        appendLocalReflectionTrace(
                                                            context = context.applicationContext,
                                                            message = "UPSTREAM local-branch-enter selectedTarget=LOCAL",
                                                        )
                                                        appendLocalReflectionTrace(
                                                            context = context.applicationContext,
                                                            message = buildLocalRouteDiagnosticTrace(
                                                                stage = "local_route_entered",
                                                                context = localRouteDiagnosticContext,
                                                            ),
                                                        )
                                                        if (isLocalInferenceRunning) return@launch
                                                        localStopRequested = false
                                                        didReceiveRealLocalPartial = false
                                                        realLocalPartialChunkCount = 0
                                                        localStreamingResponseText = null
                                                        showDelayedLocalRespondingPlaceholder = false
                                                        isLocalInferenceRunning = true
                                                        val localRunGuardEpoch = streamingGuardEpoch
                                                        val localRunStartedAtMs = SystemClock.elapsedRealtime()
                                                        val localRunStartedAtNs = SystemClock.elapsedRealtimeNanos()
                                                        val localRouteTimedOut = AtomicBoolean(false)
                                                        val gpuRouteProgressTracker = GpuRouteProgressTracker(
                                                            runStartedAtMs = localRunStartedAtMs,
                                                        )
                                                        var localGpuWatchdogForRun: Job? = null
                                                        try {
                                                            localInferenceEngineState = resolveLocalPreparingUiState()
                                                            localStreamingResponseText = null
                                                            showDelayedLocalRespondingPlaceholder = false
                                                            didReceiveRealLocalPartial = false
                                                            realLocalPartialChunkCount = 0
                                                            assistantUpdateCountForDev = 0
                                                            firstNonEmptyAssistantChunkSeenForDev = false
                                                            lastStreamingAssistantChunkForDev = null
                                                            localStreamingUiMetricsForDev.reset()
                                                            if (BuildConfig.DEBUG && DEV_UI_DEBUG_MODE) {
                                                                devRunnerWhitespaceTraceText = null
                                                            }
                                                            var measuredModelLoadDurationNs: Long? = null
