@Composable
private fun CopyableDebugBlock(
    text: String,
    title: String? = null,
    onCopy: () -> Unit,
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(8.dp),
    ) {
        Column(
            modifier = Modifier.fillMaxWidth(),
        ) {
            if (!title.isNullOrBlank()) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.labelSmall,
                    color = Color.Red,
                )
            }
            Text(
                text = text,
                style = MaterialTheme.typography.labelSmall,
                color = Color.Red,
            )
        }
        IconButton(
            onClick = onCopy,
            modifier = Modifier
                .align(Alignment.TopEnd)
                .semantics { contentDescription = "デバッグテキストをコピー" },
        ) {
            Icon(
                imageVector = Icons.Default.ContentCopy,
                contentDescription = "デバッグテキストをコピー",
                tint = Color.Red,
            )
        }
    }
}

internal fun extractNpuStandardRouteActualDisplayText(text: String?): String? {
    if (text.isNullOrBlank()) return null
    val raw = text.lineSequence()
        .firstOrNull { it.startsWith("actual_display_text=") }
        ?.substringAfter("=", missingDelimiterValue = "")
        ?.trim()
        ?: return null
    return raw
        .replace("\\n", "\n")
        .replace("\\t", "\t")
        .takeIf { it.isNotBlank() && it != "unavailable" }
}

internal fun hasNpuStandardRouteDevDiagnostics(vararg textBlocks: String?): Boolean =
    textBlocks.any { !it.isNullOrBlank() }

internal fun shouldShowNpuTrueEngineHolderStandaloneDevDiagnostics(
    routeText: String?,
    devTraceText: String?,
    s4Text: String?,
): Boolean =
    BuildConfig.DEBUG &&
        BuildConfig.TRUE_ENGINE_NPU_PROBE_FLAVOR &&
        !hasNpuStandardRouteDevDiagnostics(routeText, devTraceText, s4Text)

internal fun shouldShowNpuStandardRouteDevDiagnosticsContent(expanded: Boolean): Boolean = expanded

internal fun npuStandardRouteDevDiagnosticsToggleLabel(expanded: Boolean): String =
    if (expanded) {
        "▼ DEV診断を隠す"
    } else {
        "▶ DEV診断を表示"
    }

@Composable
