@Composable
private fun AttachmentPreviewRow(
    uris: List<Uri>,
    onOpen: (Int) -> Unit,
    onRemoveAt: (Int) -> Unit,
    inComposer: Boolean = false,
) {
    val attachmentPreviewSize = 72.dp
    val edgeFadeWidth = 12.dp
    val epsilonPx = 2
    val listState = rememberSaveable(saver = LazyListState.Saver) { LazyListState() }
    val surfaceColor = MaterialTheme.colorScheme.surface
    val showLeftFade by remember {
        derivedStateOf {
            listState.firstVisibleItemIndex > 0 || listState.firstVisibleItemScrollOffset > 0
        }
    }
    val showRightFade by remember {
        derivedStateOf {
            val layoutInfo = listState.layoutInfo
            val visibleItems = layoutInfo.visibleItemsInfo
            val totalItemsCount = layoutInfo.totalItemsCount
            val lastVisibleIndex = visibleItems.lastOrNull()?.index ?: -1
            val lastVisibleItem = visibleItems.lastOrNull()

            totalItemsCount > 0 && (
                lastVisibleIndex < totalItemsCount - 1 ||
                    (
                        lastVisibleItem != null &&
                            (lastVisibleItem.offset + lastVisibleItem.size) >
                            (layoutInfo.viewportEndOffset + epsilonPx)
                        )
                )
        }
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            // 入力欄との視認分離に必要な最小限の余白
            .padding(
                horizontal = if (inComposer) 12.dp else 17.dp,
                // 入力欄内表示時の上側余白を +2dp 調整して縁との距離を確保
                vertical = if (inComposer) 3.5.dp else 8.dp,
            ),
    ) {
        LazyRow(
            state = listState,
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(2.dp),
        ) {
            itemsIndexed(uris) { index, uri ->
                Box(
                    modifier = Modifier
                        .size(attachmentPreviewSize),
                ) {
                    Box(
                        modifier = Modifier
                            .matchParentSize()
                            .clip(RoundedCornerShape(12.dp))
                            .border(
                                width = 1.dp,
                                color = MaterialTheme.colorScheme.outlineVariant,
                                shape = RoundedCornerShape(12.dp),
                            ),
                    ) {
                        AndroidView(
                            factory = { context ->
                                ImageView(context).apply {
                                    scaleType = ImageView.ScaleType.CENTER_CROP
                                }
                            },
                            update = { imageView ->
                                imageView.setImageURI(uri)
                            },
                            modifier = Modifier
                                .fillMaxSize()
                                .background(MaterialTheme.colorScheme.surfaceVariant)
                                .clickable { onOpen(index) },
                        )
                    }

                    Box(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(top = 1.dp, end = 1.dp)
                            .size(28.dp)
                            .clip(CircleShape)
                            .clickable { onRemoveAt(index) }
                            .testTag("attachment_remove_$index"),
                        contentAlignment = Alignment.Center,
                    ) {
                        Box(
                            modifier = Modifier
                                .size(24.dp)
                                .clip(CircleShape)
                                .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.75f))
                                .border(
                                    width = 1.dp,
                                    color = MaterialTheme.colorScheme.outlineVariant,
                                    shape = CircleShape,
                                ),
                            contentAlignment = Alignment.Center,
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Close,
                                contentDescription = "Remove attachment",
                                modifier = Modifier.size(14.dp),
                            )
                        }
                    }
                }
            }
        }

        if (showLeftFade) {
            Box(
                modifier = Modifier
                    .align(Alignment.CenterStart)
                    .height(attachmentPreviewSize)
                    .width(edgeFadeWidth)
                    .background(
                        brush = Brush.horizontalGradient(
                            colors = listOf(
                                surfaceColor.copy(alpha = 1f),
                                surfaceColor.copy(alpha = 0f),
                            ),
                        ),
                    ),
            )
        }

        if (showRightFade) {
            Box(
                modifier = Modifier
                    .align(Alignment.CenterEnd)
                    .height(attachmentPreviewSize)
                    .width(edgeFadeWidth)
                    .background(
                        brush = Brush.horizontalGradient(
                            colors = listOf(
                                surfaceColor.copy(alpha = 0f),
                                surfaceColor.copy(alpha = 1f),
                            ),
                        ),
                    ),
            )
        }
    }
}

internal fun filterChatsByTitle(chats: List<Chat>, query: String): List<Chat> {
    val normalizedQuery = query.trim()
    if (normalizedQuery.isEmpty()) {
        return chats
    }
    return chats.filter { chat ->
        chat.title.contains(normalizedQuery, ignoreCase = true)
    }
}


internal fun formatChatPreview(message: String?): String {
    if (message.isNullOrBlank()) {
        return ""
    }
    val oneLineMessage = message
        .replace("\n", " ")
        .replace("\r", " ")
        .trim()
    if (oneLineMessage.isEmpty()) {
        return ""
    }
    val maxLength = 80
    return if (oneLineMessage.length > maxLength) {
        oneLineMessage.take(maxLength) + "…"
    } else {
        oneLineMessage
    }
}


internal fun resolveDefaultChatId(explicitChatId: Int?, chats: List<Chat>): Int? {
    return explicitChatId
}

internal suspend fun createAndNavigateToNewChat(
    createNewChat: suspend () -> Int,
    onChatResolved: (Int) -> Unit,
    navigateToChat: (Int) -> Unit,
    closeDrawer: suspend () -> Unit,
) {
    val newChatId = createNewChat()
    onChatResolved(newChatId)
    closeThenNavigate(
        closeDrawer = closeDrawer,
        navigate = {
            navigateToChat(newChatId)
        }
    )
}

internal suspend fun closeThenNavigate(
    closeDrawer: suspend () -> Unit,
    navigate: () -> Unit,
) {
    // close の失敗は吸収し、navigate は必ず実行する
    runCatching { closeDrawer() }
    navigate()
}

private suspend fun closeDrawerSafely(drawerState: DrawerState) {
    if (!drawerState.isOpen) {
        return
    }
    runCatching { drawerState.close() }
}

private suspend fun closeDrawerForNavigation(drawerState: DrawerState) {
    if (!drawerState.isOpen) return
    if (RuntimeFlags.isUiTestRuntime()) {
        runCatching { drawerState.snapTo(DrawerValue.Closed) }
    } else {
        runCatching { drawerState.close() }
    }
}

internal fun shouldAutoCreateNewChat(
    suppressAutoNewChat: Boolean,
    resolvedChatId: Int?,
    isCreatingChat: Boolean,
): Boolean {
    return !suppressAutoNewChat && resolvedChatId == null && !isCreatingChat
}

internal fun shouldEnterNpuStandardRouteS1(
    enabled: Boolean,
    selectedInferenceTarget: InferenceTarget,
    hasImageInput: Boolean,
    requestPrompt: String,
): Boolean =
    enabled &&
        selectedInferenceTarget == InferenceTarget.LOCAL &&
        !hasImageInput &&
        requestPrompt.isNotBlank()

internal fun shouldEnterLocalLiteRtRouteAfterNpuS1Decision(
    shouldEnterNpuS1: Boolean,
    selectedInferenceTarget: InferenceTarget,
    hasImageInput: Boolean,
    requestPrompt: String,
): Boolean =
    !shouldEnterNpuS1 &&
        selectedInferenceTarget == InferenceTarget.LOCAL &&
        !hasImageInput &&
        requestPrompt.isNotBlank()

internal fun shouldFallbackNpuStandardRouteFailureToLocal(
    result: NpuStandardRouteS1Result,
): Boolean {
    if (result.successCriteriaMet) return false
    if (result.reason == NpuStandardRouteS1Contract.REASON_COMPLETED_ROUTE_KILL_SWITCH_DISABLED) return false
    if (result.reason == NpuStandardRouteS1Contract.REASON_MODEL_NOT_NPU_COMPATIBLE) return false
    if (result.reason == NpuStandardRouteS1ProviderSelector.REASON_NATIVE_ROUTE_BLOCKED_FOR_NORMAL_CHAT) return false
    return result.reason.startsWith("adapter_failure", ignoreCase = true) ||
        result.nativeDiagnostics.nativeLinkFailureDetected == "true" ||
        result.nativeDiagnostics.nativeErrorClass == "UnsatisfiedLinkError" ||
        result.nativeDiagnostics.nativeErrorMessage.contains("UnsatisfiedLinkError", ignoreCase = true)
}

internal fun resolveNpuStandardRouteLocalFallbackBackend(
    preferredBackend: PreferredBackendDryRunSetting,
): PreferredBackendDryRunSetting =
    when (preferredBackend) {
        PreferredBackendDryRunSetting.NPU,
        PreferredBackendDryRunSetting.QUALCOMM_QNN_NPU,
        PreferredBackendDryRunSetting.DEFAULT -> PreferredBackendDryRunSetting.GPU
        PreferredBackendDryRunSetting.CPU,
        PreferredBackendDryRunSetting.GPU -> preferredBackend
    }

internal fun buildNpuStandardRouteFallbackFailureMessage(
    localFailureDiagnosticsText: String?,
): String {
    val diagnosticsText = localFailureDiagnosticsText.orEmpty()
    return if (isUnsupportedModelSignatureFailure(diagnosticsText)) {
        "NPU推論エンジンの初期化に失敗しました。選択中のQualcomm向けモデルは、現在のアプリ内ランタイムでは対応していない形式の可能性があります。"
    } else {
        "NPU推論に失敗し、GPU/CPU fallback でも応答を生成できませんでした。"
    }
}

internal fun buildNpuStandardRouteFallbackLocalFailureReason(
    localFailureDiagnosticsText: String?,
): String {
    val diagnosticsText = localFailureDiagnosticsText.orEmpty()
    return if (isUnsupportedModelSignatureFailure(diagnosticsText)) {
        "adapter_failure:UnsupportedModelSignature"
    } else {
        "unavailable"
    }
}

private fun isUnsupportedModelSignatureFailure(diagnosticsText: String): Boolean =
    diagnosticsText.contains("unsupported_model_signature_detected=true", ignoreCase = true) ||
        diagnosticsText.contains("Unsupported model signature", ignoreCase = true)

internal data class NpuStandardRouteS1ModelEligibility(
    val selectedModelName: String,
    val selectedModelFile: String,
    val npuModelEligible: Boolean,
)

internal fun resolveNpuStandardRouteS1ModelEligibility(
    selectedModelName: String?,
    selectedModelFile: String?,
): NpuStandardRouteS1ModelEligibility {
    val modelName = selectedModelName?.trim().orEmpty()
    val modelFile = selectedModelFile
        ?.trim()
        ?.takeIf { it.isNotBlank() }
        ?.let { path -> File(path).name.ifBlank { path } }
        .orEmpty()
    val eligibleText = listOf(modelName, modelFile)
        .joinToString(separator = " ")
        .lowercase(Locale.ROOT)
    val eligible = NPU_STANDARD_ROUTE_S1_MODEL_ELIGIBLE_MARKERS.any { marker ->
        marker in eligibleText
    }
    return NpuStandardRouteS1ModelEligibility(
        selectedModelName = modelName.ifBlank { "unknown" },
        selectedModelFile = modelFile.ifBlank { "unknown" },
        npuModelEligible = eligible,
    )
}

