        rawOutput = "",
        sanitizedOutput = "",
        qualityClassification = FailureNpuStandardRouteS1Provider.QUALITY_UNKNOWN,
        runDecodeReached = false,
        npuBackendEvidence = "",
        fallbackUsed = false,
        timeout = false,
        freshCrash = false,
        selectedModelName = eligibility.selectedModelName,
        selectedModelFile = eligibility.selectedModelFile,
